-- Seshhon database setup. Paste this whole file into the Supabase SQL editor and press Run.
-- Run it once on a new project. (Generated by tools/live/build-setup.sh from supabase/migrations and supabase/examples.sql.)

-- ======================= 0001_init.sql
-- Seshhon database, first version.
-- Run this once in a new Supabase project (SQL editor, or `supabase db push`).
-- It creates the tables, the access rules (who can see and change what),
-- and the functions the app calls for status, deal codes and locking a sesh.

-- ---------------------------------------------------------------- types
create type public.status_colour as enum ('on', 'thinking', 'off');
create type public.friendship_state as enum ('requested', 'accepted', 'blocked');
create type public.deal_type as enum ('Food', 'Drinks', 'Entry', 'Events');

-- ---------------------------------------------------------------- tables
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 24),
  -- Sign-up is refused unless the person confirms they are 18 or over.
  adult_confirmed_at timestamptz not null,
  push_token text,
  created_at timestamptz not null default now()
);

create table public.friendships (
  id uuid primary key default gen_random_uuid(),
  requester uuid not null references public.profiles (id) on delete cascade,
  addressee uuid not null references public.profiles (id) on delete cascade,
  state public.friendship_state not null default 'requested',
  created_at timestamptz not null default now(),
  check (requester <> addressee)
);
-- One row per pair of people, whoever asked first.
create unique index friendships_pair on public.friendships (least(requester, addressee), greatest(requester, addressee));

create table public.statuses (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  colour public.status_colour not null default 'off',
  expires_at timestamptz,
  updated_at timestamptz not null default now()
);

create table public.venues (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  kind text,
  lat double precision,
  lng double precision,
  closes text,
  places_id text
);

-- People who may enter deals and confirm codes for a venue.
create table public.venue_staff (
  venue_id uuid not null references public.venues (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  primary key (venue_id, user_id)
);

create table public.deals (
  id uuid primary key default gen_random_uuid(),
  venue_id uuid not null references public.venues (id) on delete cascade,
  type public.deal_type not null,
  title text not null check (char_length(title) between 3 and 80),
  start_time time not null,
  end_time time not null,
  is_alcohol boolean not null default false,
  discount_pct integer check (discount_pct between 0 and 100),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  check (end_time > start_time),
  -- Limits from the WA policy on responsible promotion of liquor, applied to
  -- every alcohol deal: at most 50% off, at most 60 minutes, finished by 7pm.
  -- Have a liquor lawyer confirm these before changing them.
  constraint alcohol_discount_limit check (not is_alcohol or coalesce(discount_pct, 0) <= 50),
  constraint alcohol_length_limit check (not is_alcohol or end_time - start_time <= interval '60 minutes'),
  constraint alcohol_ends_by_7pm check (not is_alcohol or end_time <= time '19:00')
);

create table public.seshes (
  id uuid primary key default gen_random_uuid(),
  creator uuid not null references public.profiles (id) on delete cascade,
  locked_venue uuid references public.venues (id),
  created_at timestamptz not null default now(),
  ended_at timestamptz
);

create table public.sesh_members (
  sesh_id uuid not null references public.seshes (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (sesh_id, user_id)
);

create table public.venue_votes (
  sesh_id uuid not null references public.seshes (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  venue_id uuid not null references public.venues (id) on delete cascade,
  voted_at timestamptz not null default now(),
  primary key (sesh_id, user_id)
);

create table public.redemptions (
  id uuid primary key default gen_random_uuid(),
  deal_id uuid not null references public.deals (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  code text not null,
  -- The night the code belongs to. A night runs until 5am, so 1am counts as the night before.
  night date not null,
  expires_at timestamptz not null,
  confirmed_at timestamptz,
  confirmed_by uuid references public.profiles (id),
  -- One use per person, per deal, per night.
  unique (deal_id, user_id, night)
);

create table public.ratings (
  venue_id uuid not null references public.venues (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  stars integer not null check (stars between 1 and 5),
  tags text[] not null default '{}',
  updated_at timestamptz not null default now(),
  primary key (venue_id, user_id)
);

-- ---------------------------------------------------------------- helpers
-- These run with the table owner's rights so access rules can call them
-- without the rules checking themselves in a loop.

create function public.are_friends(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.friendships f
    where f.state = 'accepted'
      and ((f.requester = a and f.addressee = b) or (f.requester = b and f.addressee = a))
  );
$$;

create function public.is_sesh_member(s uuid, u uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.sesh_members m where m.sesh_id = s and m.user_id = u);
$$;

create function public.sesh_creator(s uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select creator from public.seshes where id = s;
$$;

create function public.is_venue_staff(v uuid, u uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.venue_staff vs where vs.venue_id = v and vs.user_id = u);
$$;

-- The pilot runs in Perth, so deal hours and "tonight" use Perth time.
create function public.local_now(at timestamptz default now()) returns timestamp
language sql stable as $$ select at at time zone 'Australia/Perth'; $$;

create function public.night_of(at timestamptz default now()) returns date
language sql stable as $$ select (public.local_now(at) - interval '5 hours')::date; $$;

create function public.deal_is_running(d public.deals, at timestamptz default now()) returns boolean
language sql stable as $$
  select d.active and public.local_now(at)::time >= d.start_time and public.local_now(at)::time < d.end_time;
$$;

-- A venue can run at most two alcohol deals at a time.
create function public.check_alcohol_deal_count() returns trigger
language plpgsql as $$
begin
  if new.is_alcohol and new.active and (
    select count(*) from public.deals d
    where d.venue_id = new.venue_id and d.is_alcohol and d.active and d.id <> new.id
  ) >= 2 then
    raise exception 'A venue can run at most two alcohol deals per day.';
  end if;
  return new;
end;
$$;
create trigger deals_alcohol_count before insert or update on public.deals
  for each row execute function public.check_alcohol_deal_count();

-- ---------------------------------------------------------------- functions the app calls

-- Set your status. On lasts 4 hours, Thinking 2 hours, Off has no end.
create function public.set_status(new_colour public.status_colour) returns public.statuses
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  result public.statuses;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  insert into public.statuses (user_id, colour, expires_at, updated_at)
  values (
    me, new_colour,
    case new_colour when 'on' then now() + interval '4 hours' when 'thinking' then now() + interval '2 hours' else null end,
    now()
  )
  on conflict (user_id) do update
    set colour = excluded.colour, expires_at = excluded.expires_at, updated_at = excluded.updated_at
  returning * into result;
  return result;
end;
$$;

-- Turn expired statuses Off. Scheduled every five minutes at the end of this file.
create function public.expire_statuses() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  update public.statuses set colour = 'off', expires_at = null, updated_at = now()
  where colour <> 'off' and expires_at <= now();
  get diagnostics n = row_count;
  return n;
end;
$$;

-- Get a code for a deal. Fails if the deal is not running or you used it tonight.
create function public.request_deal_code(p_deal uuid) returns public.redemptions
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  d public.deals;
  r public.redemptions;
  tonight date := public.night_of();
  fresh text := 'SESH-' || (1000 + floor(random() * 9000))::int;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  select * into d from public.deals where id = p_deal;
  if not found then raise exception 'That deal does not exist.'; end if;
  if not public.deal_is_running(d) then raise exception 'That deal is not running right now.'; end if;

  select * into r from public.redemptions where deal_id = p_deal and user_id = me and night = tonight;
  if found and r.confirmed_at is not null then
    raise exception 'You have already used this deal tonight.';
  end if;
  if found and r.expires_at > now() then
    return r; -- the code you already have is still good
  end if;

  insert into public.redemptions (deal_id, user_id, code, night, expires_at)
  values (p_deal, me, fresh, tonight, now() + interval '15 minutes')
  on conflict (deal_id, user_id, night) do update
    set code = excluded.code, expires_at = excluded.expires_at
  returning * into r;
  return r;
end;
$$;

-- Venue staff confirm a code. Works once, only for their own venue, only before it runs out.
create function public.confirm_deal_code(p_code text) returns public.redemptions
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  r public.redemptions;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  select red.* into r
  from public.redemptions red
  join public.deals d on d.id = red.deal_id
  where red.code = p_code and red.night = public.night_of() and public.is_venue_staff(d.venue_id, me)
  order by red.expires_at desc
  limit 1;
  if not found then raise exception 'That code is not valid at your venue tonight.'; end if;
  if r.confirmed_at is not null then raise exception 'That code has already been used.'; end if;
  if r.expires_at <= now() then raise exception 'That code has run out. Ask for a new one.'; end if;
  update public.redemptions set confirmed_at = now(), confirmed_by = me where id = r.id returning * into r;
  return r;
end;
$$;

-- Start a sesh. You must be On, and you join it straight away.
create function public.start_sesh() returns public.seshes
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  s public.seshes;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.statuses where user_id = me and colour = 'on' and expires_at > now()) then
    raise exception 'You need to be On to start a sesh.';
  end if;
  insert into public.seshes (creator) values (me) returning * into s;
  insert into public.sesh_members (sesh_id, user_id) values (s.id, me);
  return s;
end;
$$;

-- Lock in the venue with the most votes. Ties go to the venue that got its votes first.
create function public.lock_sesh(p_sesh uuid) returns public.seshes
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  s public.seshes;
  winner uuid;
begin
  select * into s from public.seshes where id = p_sesh;
  if not found or s.creator <> me then raise exception 'Only the person who started the sesh can lock it in.'; end if;
  select venue_id into winner
  from public.venue_votes where sesh_id = p_sesh
  group by venue_id
  order by count(*) desc, min(voted_at) asc
  limit 1;
  if winner is null then raise exception 'Nobody has voted yet.'; end if;
  update public.seshes set locked_venue = winner where id = p_sesh returning * into s;
  return s;
end;
$$;

-- Average rating per venue.
create view public.venue_ratings with (security_invoker = true) as
  select venue_id, round(avg(stars)::numeric, 1) as average, count(*) as ratings
  from public.ratings group by venue_id;

-- ---------------------------------------------------------------- access rules
alter table public.profiles enable row level security;
alter table public.friendships enable row level security;
alter table public.statuses enable row level security;
alter table public.venues enable row level security;
alter table public.venue_staff enable row level security;
alter table public.deals enable row level security;
alter table public.seshes enable row level security;
alter table public.sesh_members enable row level security;
alter table public.venue_votes enable row level security;
alter table public.redemptions enable row level security;
alter table public.ratings enable row level security;

-- Profiles: you see yourself, your friends, and people with a pending request to or from you.
create policy profiles_read on public.profiles for select to authenticated using (
  id = auth.uid() or exists (
    select 1 from public.friendships f
    where f.state <> 'blocked'
      and ((f.requester = auth.uid() and f.addressee = profiles.id) or (f.addressee = auth.uid() and f.requester = profiles.id))
  )
);
create policy profiles_insert on public.profiles for insert to authenticated with check (id = auth.uid());
create policy profiles_update on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

-- Friendships: only the two people involved. Only the person asked can accept.
create policy friendships_read on public.friendships for select to authenticated
  using (requester = auth.uid() or addressee = auth.uid());
create policy friendships_request on public.friendships for insert to authenticated
  with check (requester = auth.uid() and state = 'requested');
create policy friendships_answer on public.friendships for update to authenticated
  using (addressee = auth.uid()) with check (addressee = auth.uid());
create policy friendships_remove on public.friendships for delete to authenticated
  using (requester = auth.uid() or addressee = auth.uid());

-- Statuses: you see your own. Friends see yours only while it is On or Thinking and not run out.
-- Changes go through set_status(), so there are no insert or update rules here.
create policy statuses_read on public.statuses for select to authenticated using (
  user_id = auth.uid()
  or (colour <> 'off' and expires_at > now() and public.are_friends(user_id, auth.uid()))
);

-- Venues and deals: any signed-in person can read. Venue staff manage their own deals.
create policy venues_read on public.venues for select to authenticated using (true);
create policy venue_staff_read on public.venue_staff for select to authenticated using (user_id = auth.uid());
create policy deals_read on public.deals for select to authenticated using (true);
create policy deals_insert on public.deals for insert to authenticated with check (public.is_venue_staff(venue_id, auth.uid()));
create policy deals_update on public.deals for update to authenticated
  using (public.is_venue_staff(venue_id, auth.uid())) with check (public.is_venue_staff(venue_id, auth.uid()));

-- Seshes: the creator, the members, and the creator's friends (so they can join).
create policy seshes_read on public.seshes for select to authenticated using (
  creator = auth.uid() or public.is_sesh_member(id, auth.uid()) or public.are_friends(creator, auth.uid())
);
create policy seshes_end on public.seshes for update to authenticated using (creator = auth.uid()) with check (creator = auth.uid());

create policy members_read on public.sesh_members for select to authenticated using (
  user_id = auth.uid() or public.is_sesh_member(sesh_id, auth.uid()) or public.are_friends(public.sesh_creator(sesh_id), auth.uid())
);
create policy members_join on public.sesh_members for insert to authenticated with check (
  user_id = auth.uid() and public.are_friends(public.sesh_creator(sesh_id), auth.uid())
);
create policy members_leave on public.sesh_members for delete to authenticated using (user_id = auth.uid());

-- Votes: members of the sesh see them; each member casts or changes only their own.
create policy votes_read on public.venue_votes for select to authenticated using (public.is_sesh_member(sesh_id, auth.uid()));
create policy votes_cast on public.venue_votes for insert to authenticated
  with check (user_id = auth.uid() and public.is_sesh_member(sesh_id, auth.uid()));
create policy votes_change on public.venue_votes for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid() and public.is_sesh_member(sesh_id, auth.uid()));
create policy votes_remove on public.venue_votes for delete to authenticated using (user_id = auth.uid());

-- Redemptions: you see your own. Codes are made and confirmed only through the functions above.
create policy redemptions_read on public.redemptions for select to authenticated using (user_id = auth.uid());

-- Ratings: anyone signed in can read; you write only your own.
create policy ratings_read on public.ratings for select to authenticated using (true);
create policy ratings_insert on public.ratings for insert to authenticated with check (user_id = auth.uid());
create policy ratings_update on public.ratings for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ---------------------------------------------------------------- permissions
grant usage on schema public to authenticated;
grant select, insert, update on public.profiles to authenticated;
grant select, insert, delete on public.friendships to authenticated;
-- The person asked can change only the state (accept or block), not who the request is between.
grant update (state) on public.friendships to authenticated;
grant select on public.statuses, public.venues, public.venue_staff, public.redemptions, public.venue_ratings to authenticated;
grant select, insert, update on public.deals to authenticated;
grant select, update on public.seshes to authenticated;
grant select, insert, delete on public.sesh_members to authenticated;
grant select, insert, update, delete on public.venue_votes to authenticated;
grant select, insert, update on public.ratings to authenticated;

revoke execute on all functions in schema public from public;
grant execute on function
  public.are_friends(uuid, uuid), public.is_sesh_member(uuid, uuid), public.sesh_creator(uuid),
  public.is_venue_staff(uuid, uuid), public.local_now(timestamptz), public.night_of(timestamptz),
  public.deal_is_running(public.deals, timestamptz), public.set_status(public.status_colour),
  public.request_deal_code(uuid), public.confirm_deal_code(text), public.start_sesh(), public.lock_sesh(uuid)
to authenticated;

-- ---------------------------------------------------------------- schedule
-- Turn expired statuses Off every five minutes, if the pg_cron extension is switched on
-- (Supabase dashboard: Database, Extensions, pg_cron). Without it, expired statuses are
-- still hidden from friends by the access rule above; they just stay stored until changed.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('seshhon-expire-statuses', '*/5 * * * *', 'select public.expire_statuses()');
  end if;
end;
$$;

-- ======================= 0002_live_web_app.sql
-- Seshhon database, second step: everything the live web app needs.
-- Adds invite links, a single "give me everything" call for the app, and the
-- remaining actions (join, vote, end a sesh, rate, delete account).

-- ---------------------------------------------------------------- invite codes
-- Eight characters from an alphabet with no look-alikes (no I, L, O, 0 or 1).
create function public.new_invite_code() returns text
language sql volatile as $$
  select string_agg(substr('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + floor(random() * 31)::int, 1), '')
  from generate_series(1, 8);
$$;

alter table public.profiles add column invite_code text;
update public.profiles set invite_code = public.new_invite_code() where invite_code is null;
alter table public.profiles alter column invite_code set default public.new_invite_code();
alter table public.profiles alter column invite_code set not null;
alter table public.profiles add constraint profiles_invite_code_unique unique (invite_code);

-- Example venues are marked so the app can label them as examples.
alter table public.venues add column is_example boolean not null default false;

-- ---------------------------------------------------------------- tighter helpers
-- The helpers only answer questions about the person asking, so nobody can use
-- them to check on two other people.

create or replace function public.are_friends(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select (auth.uid() = a or auth.uid() = b) and exists (
    select 1 from public.friendships f
    where f.state = 'accepted'
      and ((f.requester = a and f.addressee = b) or (f.requester = b and f.addressee = a))
  );
$$;

create or replace function public.is_sesh_member(s uuid, u uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() = u and exists (select 1 from public.sesh_members m where m.sesh_id = s and m.user_id = u);
$$;

create or replace function public.is_venue_staff(v uuid, u uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() = u and exists (select 1 from public.venue_staff vs where vs.venue_id = v and vs.user_id = u);
$$;

-- True when the person asking (b) is in a live sesh with a.
create function public.shares_sesh(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() = b and exists (
    select 1
    from public.sesh_members m1
    join public.sesh_members m2 on m2.sesh_id = m1.sesh_id
    join public.seshes s on s.id = m1.sesh_id
    where m1.user_id = a and m2.user_id = b
      and s.ended_at is null and s.created_at > now() - interval '8 hours'
  );
$$;

-- True while the person asking is On or Thinking.
create function public.i_am_visible() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.statuses s
    where s.user_id = auth.uid() and s.colour <> 'off' and s.expires_at > now()
  );
$$;

-- Fair's fair: while you are Off you cannot see who else is On, or their seshes.
drop policy statuses_read on public.statuses;
create policy statuses_read on public.statuses for select to authenticated using (
  user_id = auth.uid()
  or (colour <> 'off' and expires_at > now() and public.are_friends(user_id, auth.uid()) and public.i_am_visible())
);

drop policy seshes_read on public.seshes;
create policy seshes_read on public.seshes for select to authenticated using (
  creator = auth.uid() or public.is_sesh_member(id, auth.uid())
  or (public.are_friends(creator, auth.uid()) and public.i_am_visible())
);

drop policy members_read on public.sesh_members;
create policy members_read on public.sesh_members for select to authenticated using (
  user_id = auth.uid() or public.is_sesh_member(sesh_id, auth.uid())
  or (public.are_friends(public.sesh_creator(sesh_id), auth.uid()) and public.i_am_visible())
);

-- People in the same live sesh can see each other's name.
create policy profiles_read_sesh on public.profiles for select to authenticated
  using (public.shares_sesh(id, auth.uid()));

-- The person who started a sesh can rejoin it after leaving.
drop policy members_join on public.sesh_members;
create policy members_join on public.sesh_members for insert to authenticated with check (
  user_id = auth.uid()
  and (public.sesh_creator(sesh_id) = auth.uid() or public.are_friends(public.sesh_creator(sesh_id), auth.uid()))
);

-- ---------------------------------------------------------------- sign-up and friends

create function public.api_sign_up(p_name text, p_adult boolean) returns jsonb
language plpgsql security invoker set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if p_adult is not true then raise exception 'Seshhon is for people aged 18 and over.'; end if;
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 24 then
    raise exception 'Enter a first name of up to 24 characters.';
  end if;
  insert into public.profiles (id, name, adult_confirmed_at)
  values (auth.uid(), btrim(p_name), now())
  on conflict (id) do update set name = excluded.name;
  return '{}'::jsonb;
end;
$$;

-- Opening someone's invite link sends them a friend request. They still have to accept,
-- unless they had already asked you, in which case you are now friends.
create function public.request_friend(p_code text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  other public.profiles;
  f public.friendships;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.profiles where id = me) then raise exception 'Finish signing up first.'; end if;
  select * into other from public.profiles where invite_code = upper(btrim(coalesce(p_code, '')));
  if not found then raise exception 'That invite link is not valid.'; end if;
  if other.id = me then raise exception 'That is your own invite link.'; end if;

  select * into f from public.friendships
  where (requester = me and addressee = other.id) or (requester = other.id and addressee = me);
  if found then
    if f.state = 'blocked' then raise exception 'That invite link is not valid.'; end if;
    if f.state = 'requested' and f.addressee = me then
      update public.friendships set state = 'accepted' where id = f.id;
      return jsonb_build_object('name', other.name, 'state', 'accepted');
    end if;
    return jsonb_build_object('name', other.name, 'state', f.state);
  end if;

  insert into public.friendships (requester, addressee) values (me, other.id);
  return jsonb_build_object('name', other.name, 'state', 'requested');
end;
$$;

-- Accept a request, or (with p_accept false) decline it, cancel it, or remove a friend.
create function public.answer_friend(p_friendship uuid, p_accept boolean) returns jsonb
language plpgsql security invoker set search_path = public as $$
begin
  if p_accept then
    update public.friendships set state = 'accepted'
    where id = p_friendship and addressee = auth.uid() and state = 'requested';
    if not found then raise exception 'That request is no longer there.'; end if;
  else
    delete from public.friendships
    where id = p_friendship and (requester = auth.uid() or addressee = auth.uid());
  end if;
  return '{}'::jsonb;
end;
$$;

-- ---------------------------------------------------------------- sesh actions

-- Starting a second sesh returns the one you already have running.
create or replace function public.start_sesh() returns public.seshes
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  s public.seshes;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.statuses where user_id = me and colour = 'on' and expires_at > now()) then
    raise exception 'You need to be On to start a sesh.';
  end if;
  select * into s from public.seshes
  where creator = me and ended_at is null and created_at > now() - interval '8 hours'
  order by created_at desc limit 1;
  if found then
    insert into public.sesh_members (sesh_id, user_id) values (s.id, me) on conflict do nothing;
    return s;
  end if;
  insert into public.seshes (creator) values (me) returning * into s;
  insert into public.sesh_members (sesh_id, user_id) values (s.id, me);
  return s;
end;
$$;

create function public.join_sesh(p_sesh uuid) returns jsonb
language plpgsql security invoker set search_path = public as $$
begin
  if not exists (
    select 1 from public.seshes
    where id = p_sesh and ended_at is null and created_at > now() - interval '8 hours'
  ) then
    raise exception 'That sesh has ended.';
  end if;
  insert into public.sesh_members (sesh_id, user_id) values (p_sesh, auth.uid()) on conflict do nothing;
  return '{}'::jsonb;
end;
$$;

create function public.leave_sesh(p_sesh uuid) returns jsonb
language plpgsql security invoker set search_path = public as $$
begin
  delete from public.venue_votes where sesh_id = p_sesh and user_id = auth.uid();
  delete from public.sesh_members where sesh_id = p_sesh and user_id = auth.uid();
  return '{}'::jsonb;
end;
$$;

-- Vote for a venue, change your vote, or (with p_venue null) take it back.
create function public.cast_vote(p_sesh uuid, p_venue uuid) returns jsonb
language plpgsql security invoker set search_path = public as $$
begin
  if not exists (
    select 1 from public.seshes
    where id = p_sesh and ended_at is null and locked_venue is null and created_at > now() - interval '8 hours'
  ) then
    raise exception 'Voting has closed for that sesh.';
  end if;
  if p_venue is null then
    delete from public.venue_votes where sesh_id = p_sesh and user_id = auth.uid();
  else
    insert into public.venue_votes (sesh_id, user_id, venue_id) values (p_sesh, auth.uid(), p_venue)
    on conflict (sesh_id, user_id) do update set venue_id = excluded.venue_id, voted_at = now();
  end if;
  return '{}'::jsonb;
end;
$$;

create function public.end_sesh(p_sesh uuid) returns jsonb
language plpgsql security invoker set search_path = public as $$
begin
  update public.seshes set ended_at = now() where id = p_sesh and creator = auth.uid();
  if not found then raise exception 'Only the person who started the sesh can end it.'; end if;
  return '{}'::jsonb;
end;
$$;

-- ---------------------------------------------------------------- ratings and account

create function public.rate_venue(p_venue uuid, p_stars integer, p_tags text[]) returns jsonb
language plpgsql security invoker set search_path = public as $$
declare
  tags text[] := coalesce(p_tags, '{}');
begin
  if coalesce(array_length(tags, 1), 0) > 5 or exists (select 1 from unnest(tags) t where char_length(t) > 24) then
    raise exception 'Too many tags.';
  end if;
  insert into public.ratings (venue_id, user_id, stars, tags, updated_at)
  values (p_venue, auth.uid(), p_stars, tags, now())
  on conflict (venue_id, user_id) do update set stars = excluded.stars, tags = excluded.tags, updated_at = now();
  return '{}'::jsonb;
end;
$$;

-- Removes the person's profile and everything attached to it.
create function public.delete_account() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
begin
  if me is null then raise exception 'Sign in first.'; end if;
  delete from public.profiles where id = me;
  begin
    delete from auth.users where id = me;
  exception when insufficient_privilege then
    null; -- the sign-in record stays, but it no longer has any Seshhon data
  end;
  return '{}'::jsonb;
end;
$$;

-- ---------------------------------------------------------------- everything the app shows, in one call
-- Runs with the caller's own rights, so the access rules decide what comes back.
create function public.api_state() returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'now', now(),
    'night', public.night_of(),
    'me', (
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'invite_code', p.invite_code,
        'colour', coalesce((select s.colour::text from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now()), 'off'),
        'expires_at', (select s.expires_at from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now())
      )
      from public.profiles p where p.id = auth.uid()
    ),
    'friends', coalesce((
      select jsonb_agg(
        jsonb_build_object('friendship', f.id, 'id', p.id, 'name', p.name, 'colour', coalesce(s.colour::text, 'off'), 'since', s.updated_at)
        order by case coalesce(s.colour::text, 'off') when 'on' then 0 when 'thinking' then 1 else 2 end, p.name
      )
      from public.friendships f
      join public.profiles p on p.id = case when f.requester = auth.uid() then f.addressee else f.requester end
      left join public.statuses s on s.user_id = p.id
      where f.state = 'accepted'
    ), '[]'::jsonb),
    'requests_in', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.requester
      where f.state = 'requested' and f.addressee = auth.uid()
    ), '[]'::jsonb),
    'requests_out', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.addressee
      where f.state = 'requested' and f.requester = auth.uid()
    ), '[]'::jsonb),
    'seshes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'mine', s.creator = auth.uid(),
          'creator_name', (select p.name from public.profiles p where p.id = s.creator),
          'locked_venue', s.locked_venue,
          'am_member', public.is_sesh_member(s.id, auth.uid()),
          'members', coalesce((
            select jsonb_agg(jsonb_build_object('id', m.user_id, 'name', p.name) order by m.joined_at)
            from public.sesh_members m left join public.profiles p on p.id = m.user_id
            where m.sesh_id = s.id
          ), '[]'::jsonb),
          'votes', coalesce((
            select jsonb_agg(jsonb_build_object('user_id', v.user_id, 'venue_id', v.venue_id, 'voted_at', v.voted_at))
            from public.venue_votes v where v.sesh_id = s.id
          ), '[]'::jsonb)
        )
        order by s.created_at desc
      )
      from public.seshes s
      where s.ended_at is null and s.created_at > now() - interval '8 hours'
    ), '[]'::jsonb),
    'venues', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', v.id, 'name', v.name, 'kind', v.kind, 'closes', v.closes, 'is_example', v.is_example,
          'average', (select r.average from public.venue_ratings r where r.venue_id = v.id),
          'ratings', coalesce((select r.ratings from public.venue_ratings r where r.venue_id = v.id), 0),
          'my_stars', coalesce((select r.stars from public.ratings r where r.venue_id = v.id and r.user_id = auth.uid()), 0),
          'my_tags', coalesce((select to_jsonb(r.tags) from public.ratings r where r.venue_id = v.id and r.user_id = auth.uid()), '[]'::jsonb)
        )
        order by v.name
      )
      from public.venues v
    ), '[]'::jsonb),
    'deals', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', d.id, 'venue_id', d.venue_id, 'type', d.type, 'title', d.title,
          'start_time', to_char(d.start_time, 'HH24:MI'), 'end_time', to_char(d.end_time, 'HH24:MI'),
          'running', public.deal_is_running(d),
          'used', coalesce(r.confirmed_at is not null, false),
          'code', case when r.confirmed_at is null and r.expires_at > now() then r.code end,
          'code_expires_at', case when r.confirmed_at is null and r.expires_at > now() then r.expires_at end
        )
        order by d.start_time, d.title
      )
      from public.deals d
      left join public.redemptions r on r.deal_id = d.id and r.user_id = auth.uid() and r.night = public.night_of()
      where d.active
    ), '[]'::jsonb),
    'staff_venues', coalesce((
      select jsonb_agg(vs.venue_id) from public.venue_staff vs where vs.user_id = auth.uid()
    ), '[]'::jsonb)
  );
$$;

-- ---------------------------------------------------------------- permissions
-- Supabase gives signed-out and signed-in visitors full rights on every new table and
-- function by default. Take all of that away, then hand back only what the app needs.
revoke all on all tables in schema public from public, anon, authenticated;
revoke execute on all functions in schema public from public, anon, authenticated;

-- Other people can read only your id, name and invite code, never your push token.
grant select (id, name, invite_code, created_at) on public.profiles to authenticated;
grant insert (id, name, adult_confirmed_at), update (name, push_token) on public.profiles to authenticated;
-- The person asked can change only the state (accept or block), not who the request is between.
grant select, insert, delete on public.friendships to authenticated;
grant update (state) on public.friendships to authenticated;
grant select on public.statuses, public.venues, public.venue_staff, public.redemptions, public.venue_ratings to authenticated;
grant select, insert, update on public.deals to authenticated;
grant select, update on public.seshes to authenticated;
grant select, insert, delete on public.sesh_members to authenticated;
grant select, insert, update, delete on public.venue_votes to authenticated;
grant select, insert, update on public.ratings to authenticated;

-- Signed-out visitors can call nothing. Signed-in people can call only what is listed.
grant execute on function
  public.are_friends(uuid, uuid), public.is_sesh_member(uuid, uuid), public.sesh_creator(uuid),
  public.is_venue_staff(uuid, uuid), public.shares_sesh(uuid, uuid), public.i_am_visible(), public.new_invite_code(),
  public.local_now(timestamptz), public.night_of(timestamptz), public.deal_is_running(public.deals, timestamptz),
  public.set_status(public.status_colour), public.request_deal_code(uuid), public.confirm_deal_code(text),
  public.start_sesh(), public.lock_sesh(uuid), public.join_sesh(uuid), public.leave_sesh(uuid),
  public.cast_vote(uuid, uuid), public.end_sesh(uuid), public.api_sign_up(text, boolean),
  public.request_friend(text), public.answer_friend(uuid, boolean), public.rate_venue(uuid, integer, text[]),
  public.delete_account(), public.api_state()
to authenticated;

-- ======================= 0003_age_gate.sql
-- Age gate: sign-up now asks for a date of birth and checks it on the server.
-- The date of birth is used for the check only. It is NOT stored; the database keeps
-- just the moment the person was confirmed as 18 or over.
-- Also lets the app label alcohol deals ("18+, ID required, drink responsibly").

drop function if exists public.api_sign_up(text, boolean);

create function public.api_sign_up(p_name text, p_birth_date date) returns jsonb
language plpgsql security invoker set search_path = public as $$
declare today date := (now() at time zone 'Australia/Perth')::date;
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if p_birth_date is null or p_birth_date > today or p_birth_date < date '1900-01-01' then
    raise exception 'Enter your date of birth.';
  end if;
  if p_birth_date > (today - interval '18 years')::date then
    raise exception 'Seshhon is for people aged 18 and over.';
  end if;
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 24 then
    raise exception 'Enter a first name of up to 24 characters.';
  end if;
  insert into public.profiles (id, name, adult_confirmed_at)
  values (auth.uid(), btrim(p_name), now())
  on conflict (id) do update set name = excluded.name;
  return '{}'::jsonb;
end;
$$;

revoke all on function public.api_sign_up(text, date) from public, anon, authenticated;
grant execute on function public.api_sign_up(text, date) to authenticated;

create or replace function public.api_state() returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'now', now(),
    'night', public.night_of(),
    'me', (
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'invite_code', p.invite_code,
        'colour', coalesce((select s.colour::text from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now()), 'off'),
        'expires_at', (select s.expires_at from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now())
      )
      from public.profiles p where p.id = auth.uid()
    ),
    'friends', coalesce((
      select jsonb_agg(
        jsonb_build_object('friendship', f.id, 'id', p.id, 'name', p.name, 'colour', coalesce(s.colour::text, 'off'), 'since', s.updated_at)
        order by case coalesce(s.colour::text, 'off') when 'on' then 0 when 'thinking' then 1 else 2 end, p.name
      )
      from public.friendships f
      join public.profiles p on p.id = case when f.requester = auth.uid() then f.addressee else f.requester end
      left join public.statuses s on s.user_id = p.id
      where f.state = 'accepted'
    ), '[]'::jsonb),
    'requests_in', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.requester
      where f.state = 'requested' and f.addressee = auth.uid()
    ), '[]'::jsonb),
    'requests_out', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.addressee
      where f.state = 'requested' and f.requester = auth.uid()
    ), '[]'::jsonb),
    'seshes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'mine', s.creator = auth.uid(),
          'creator_name', (select p.name from public.profiles p where p.id = s.creator),
          'locked_venue', s.locked_venue,
          'am_member', public.is_sesh_member(s.id, auth.uid()),
          'members', coalesce((
            select jsonb_agg(jsonb_build_object('id', m.user_id, 'name', p.name) order by m.joined_at)
            from public.sesh_members m left join public.profiles p on p.id = m.user_id
            where m.sesh_id = s.id
          ), '[]'::jsonb),
          'votes', coalesce((
            select jsonb_agg(jsonb_build_object('user_id', v.user_id, 'venue_id', v.venue_id, 'voted_at', v.voted_at))
            from public.venue_votes v where v.sesh_id = s.id
          ), '[]'::jsonb)
        )
        order by s.created_at desc
      )
      from public.seshes s
      where s.ended_at is null and s.created_at > now() - interval '8 hours'
    ), '[]'::jsonb),
    'venues', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', v.id, 'name', v.name, 'kind', v.kind, 'closes', v.closes, 'is_example', v.is_example,
          'average', (select r.average from public.venue_ratings r where r.venue_id = v.id),
          'ratings', coalesce((select r.ratings from public.venue_ratings r where r.venue_id = v.id), 0),
          'my_stars', coalesce((select r.stars from public.ratings r where r.venue_id = v.id and r.user_id = auth.uid()), 0),
          'my_tags', coalesce((select to_jsonb(r.tags) from public.ratings r where r.venue_id = v.id and r.user_id = auth.uid()), '[]'::jsonb)
        )
        order by v.name
      )
      from public.venues v
    ), '[]'::jsonb),
    'deals', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', d.id, 'venue_id', d.venue_id, 'type', d.type, 'title', d.title, 'is_alcohol', d.is_alcohol,
          'start_time', to_char(d.start_time, 'HH24:MI'), 'end_time', to_char(d.end_time, 'HH24:MI'),
          'running', public.deal_is_running(d),
          'used', coalesce(r.confirmed_at is not null, false),
          'code', case when r.confirmed_at is null and r.expires_at > now() then r.code end,
          'code_expires_at', case when r.confirmed_at is null and r.expires_at > now() then r.expires_at end
        )
        order by d.start_time, d.title
      )
      from public.deals d
      left join public.redemptions r on r.deal_id = d.id and r.user_id = auth.uid() and r.night = public.night_of()
      where d.active
    ), '[]'::jsonb),
    'staff_venues', coalesce((
      select jsonb_agg(vs.venue_id) from public.venue_staff vs where vs.user_id = auth.uid()
    ), '[]'::jsonb)
  );
$$;

-- Ratings privacy: you can only read your own ratings (stars and tags). Everyone still
-- sees the venue totals and averages, which come from a view that only exposes aggregates.
alter view public.venue_ratings set (security_invoker = false);
drop policy if exists ratings_read on public.ratings;
create policy ratings_read on public.ratings for select to authenticated using (user_id = auth.uid());

-- ======================= 0004_sesh_chat.sql
-- Sesh chat: short text messages between the people in a sesh. They are erased when the sesh
-- ends (or after 8 hours at the latest). Includes block and report.
-- Nobody reads or writes these tables directly: everything goes through the functions below.

create table public.messages (
  id uuid primary key default gen_random_uuid(),
  sesh_id uuid not null references public.seshes (id) on delete cascade,
  sender uuid not null references public.profiles (id) on delete cascade,
  body text not null check (char_length(body) between 1 and 500),
  created_at timestamptz not null default now()
);
create index messages_sesh_idx on public.messages (sesh_id, created_at);

create table public.blocks (
  blocker uuid not null references public.profiles (id) on delete cascade,
  blocked uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker, blocked),
  check (blocker <> blocked)
);

-- A report keeps a copy of the reported message so it can be looked at after the chat is erased.
-- Reports are deleted after 90 days. Only the project owner can read them (in the Supabase dashboard).
create table public.reports (
  id uuid primary key default gen_random_uuid(),
  reporter uuid references public.profiles (id) on delete set null,
  reported uuid references public.profiles (id) on delete set null,
  sesh_id uuid,
  message_body text not null,
  reason text check (char_length(reason) <= 200),
  created_at timestamptz not null default now()
);

alter table public.messages enable row level security;
alter table public.blocks enable row level security;
alter table public.reports enable row level security;
revoke all on public.messages, public.blocks, public.reports from public, anon, authenticated;

-- ---------------------------------------------------------------- helpers

create function public.sesh_is_live(s uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.seshes where id = s and ended_at is null and created_at > now() - interval '8 hours');
$$;

create function public.blocked_between(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.blocks where (blocker = a and blocked = b) or (blocker = b and blocked = a));
$$;

-- Deletes finished and old chats and old reports. Called by the functions below and, if the
-- pg_cron extension is on, every 5 minutes.
create function public.purge_chat() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  delete from public.messages m
  where m.created_at < now() - interval '8 hours'
     or exists (select 1 from public.seshes s where s.id = m.sesh_id and (s.ended_at is not null or s.created_at < now() - interval '8 hours'));
  get diagnostics n = row_count;
  delete from public.reports where created_at < now() - interval '90 days';
  return n;
end;
$$;

-- ---------------------------------------------------------------- sending and reading

create function public.send_message(p_sesh uuid, p_body text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  body text := btrim(coalesce(p_body, ''));
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not public.is_sesh_member(p_sesh, me) or not public.sesh_is_live(p_sesh) then
    raise exception 'You can only chat in a sesh you are in.';
  end if;
  if char_length(body) = 0 then raise exception 'Type a message first.'; end if;
  if char_length(body) > 500 then raise exception 'Keep messages under 500 characters.'; end if;
  if (select count(*) from public.messages where sender = me and created_at > now() - interval '1 minute') >= 20 then
    raise exception 'Slow down a little.';
  end if;
  insert into public.messages (sesh_id, sender, body) values (p_sesh, me, body);
  if random() < 0.1 then perform public.purge_chat(); end if;
  return '{}'::jsonb;
end;
$$;

create function public.get_messages(p_sesh uuid) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  out jsonb;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not public.is_sesh_member(p_sesh, me) or not public.sesh_is_live(p_sesh) then
    return '[]'::jsonb;
  end if;
  if random() < 0.05 then perform public.purge_chat(); end if;
  select coalesce(jsonb_agg(x order by x_at), '[]'::jsonb) into out from (
    select jsonb_build_object('id', m.id, 'sender', m.sender, 'name', p.name, 'body', m.body, 'at', m.created_at) as x, m.created_at as x_at
    from public.messages m
    join public.profiles p on p.id = m.sender
    where m.sesh_id = p_sesh
      and (m.sender = me or not public.blocked_between(m.sender, me))
    order by m.created_at desc
    limit 200
  ) t;
  return out;
end;
$$;

-- ---------------------------------------------------------------- block and report

create function public.block_user(p_user uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if p_user is null or p_user = me or not exists (select 1 from public.profiles where id = p_user) then
    raise exception 'That person could not be blocked.';
  end if;
  insert into public.blocks (blocker, blocked) values (me, p_user) on conflict do nothing;
  -- Blocking also ends any friendship, so they stop seeing your status.
  delete from public.friendships
  where (requester = me and addressee = p_user) or (requester = p_user and addressee = me);
  insert into public.friendships (requester, addressee, state) values (me, p_user, 'blocked');
  return '{}'::jsonb;
end;
$$;

create function public.unblock_user(p_user uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'Sign in first.'; end if;
  delete from public.blocks where blocker = me and blocked = p_user;
  delete from public.friendships where requester = me and addressee = p_user and state = 'blocked';
  return '{}'::jsonb;
end;
$$;

create function public.blocked_list() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name) order by p.name), '[]'::jsonb)
  from public.blocks b join public.profiles p on p.id = b.blocked
  where b.blocker = auth.uid();
$$;

create function public.report_message(p_message uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  m public.messages;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  select * into m from public.messages where id = p_message;
  if not found or not public.is_sesh_member(m.sesh_id, me) then raise exception 'That message is no longer there.'; end if;
  insert into public.reports (reporter, reported, sesh_id, message_body, reason)
  values (me, m.sender, m.sesh_id, m.body, left(coalesce(p_reason, ''), 200));
  return '{}'::jsonb;
end;
$$;

-- ---------------------------------------------------------------- ending a sesh erases its chat

create or replace function public.end_sesh(p_sesh uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  update public.seshes set ended_at = now() where id = p_sesh and creator = auth.uid();
  if not found then raise exception 'Only the person who started the sesh can end it.'; end if;
  delete from public.messages where sesh_id = p_sesh;
  return '{}'::jsonb;
end;
$$;

-- ---------------------------------------------------------------- permissions

revoke all on function
  public.sesh_is_live(uuid), public.blocked_between(uuid, uuid), public.purge_chat(),
  public.send_message(uuid, text), public.get_messages(uuid), public.block_user(uuid), public.unblock_user(uuid),
  public.blocked_list(), public.report_message(uuid, text)
from public, anon, authenticated;
grant execute on function
  public.send_message(uuid, text), public.get_messages(uuid), public.block_user(uuid), public.unblock_user(uuid),
  public.blocked_list(), public.report_message(uuid, text)
to authenticated;
-- The app state calls blocked_list as the signed-in person.
-- end_sesh was replaced, so give back the right to call it.
revoke all on function public.end_sesh(uuid) from public, anon;
grant execute on function public.end_sesh(uuid) to authenticated;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('seshhon-purge-chat', '*/5 * * * *', 'select public.purge_chat()');
  end if;
end;
$$;

create or replace function public.api_state() returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'now', now(),
    'night', public.night_of(),
    'me', (
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'invite_code', p.invite_code,
        'colour', coalesce((select s.colour::text from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now()), 'off'),
        'expires_at', (select s.expires_at from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now())
      )
      from public.profiles p where p.id = auth.uid()
    ),
    'friends', coalesce((
      select jsonb_agg(
        jsonb_build_object('friendship', f.id, 'id', p.id, 'name', p.name, 'colour', coalesce(s.colour::text, 'off'), 'since', s.updated_at)
        order by case coalesce(s.colour::text, 'off') when 'on' then 0 when 'thinking' then 1 else 2 end, p.name
      )
      from public.friendships f
      join public.profiles p on p.id = case when f.requester = auth.uid() then f.addressee else f.requester end
      left join public.statuses s on s.user_id = p.id
      where f.state = 'accepted'
    ), '[]'::jsonb),
    'requests_in', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.requester
      where f.state = 'requested' and f.addressee = auth.uid()
    ), '[]'::jsonb),
    'requests_out', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.addressee
      where f.state = 'requested' and f.requester = auth.uid()
    ), '[]'::jsonb),
    'seshes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'mine', s.creator = auth.uid(),
          'creator_name', (select p.name from public.profiles p where p.id = s.creator),
          'locked_venue', s.locked_venue,
          'am_member', public.is_sesh_member(s.id, auth.uid()),
          'members', coalesce((
            select jsonb_agg(jsonb_build_object('id', m.user_id, 'name', p.name) order by m.joined_at)
            from public.sesh_members m left join public.profiles p on p.id = m.user_id
            where m.sesh_id = s.id
          ), '[]'::jsonb),
          'votes', coalesce((
            select jsonb_agg(jsonb_build_object('user_id', v.user_id, 'venue_id', v.venue_id, 'voted_at', v.voted_at))
            from public.venue_votes v where v.sesh_id = s.id
          ), '[]'::jsonb)
        )
        order by s.created_at desc
      )
      from public.seshes s
      where s.ended_at is null and s.created_at > now() - interval '8 hours'
    ), '[]'::jsonb),
    'venues', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', v.id, 'name', v.name, 'kind', v.kind, 'closes', v.closes, 'is_example', v.is_example,
          'average', (select r.average from public.venue_ratings r where r.venue_id = v.id),
          'ratings', coalesce((select r.ratings from public.venue_ratings r where r.venue_id = v.id), 0),
          'my_stars', coalesce((select r.stars from public.ratings r where r.venue_id = v.id and r.user_id = auth.uid()), 0),
          'my_tags', coalesce((select to_jsonb(r.tags) from public.ratings r where r.venue_id = v.id and r.user_id = auth.uid()), '[]'::jsonb)
        )
        order by v.name
      )
      from public.venues v
    ), '[]'::jsonb),
    'deals', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', d.id, 'venue_id', d.venue_id, 'type', d.type, 'title', d.title, 'is_alcohol', d.is_alcohol,
          'start_time', to_char(d.start_time, 'HH24:MI'), 'end_time', to_char(d.end_time, 'HH24:MI'),
          'running', public.deal_is_running(d),
          'used', coalesce(r.confirmed_at is not null, false),
          'code', case when r.confirmed_at is null and r.expires_at > now() then r.code end,
          'code_expires_at', case when r.confirmed_at is null and r.expires_at > now() then r.expires_at end
        )
        order by d.start_time, d.title
      )
      from public.deals d
      left join public.redemptions r on r.deal_id = d.id and r.user_id = auth.uid() and r.night = public.night_of()
      where d.active
    ), '[]'::jsonb),
    'staff_venues', coalesce((
      select jsonb_agg(vs.venue_id) from public.venue_staff vs where vs.user_id = auth.uid()
    ), '[]'::jsonb),
    'blocked', public.blocked_list()
  );
$$;

-- ======================= 0005_age_check.sql
-- Third-party age check: a selfie age estimate, with ID plus selfie only when the estimate is unsure.
-- The check itself runs on the provider's page (Yoti or Didit) and is driven by the Edge Function
-- in supabase/functions/age-check. This database keeps only the outcome: who passed, when, which
-- provider and which method. No photo, ID, date of birth or estimated age is stored here.
--
-- Off until switched on (see README, "Age check"):
--   update public.app_settings set age_check_provider = 'yoti', age_check_required = true;
--
-- Safe to run more than once.

-- ---------------------------------------------------------------- settings (one row)
create table if not exists public.app_settings (
  id boolean primary key default true check (id),
  age_check_required boolean not null default false,
  age_check_provider text not null default 'yoti' check (age_check_provider in ('yoti', 'didit'))
);
insert into public.app_settings default values on conflict do nothing;
alter table public.app_settings enable row level security;
revoke all on public.app_settings from public, anon, authenticated;

-- ---------------------------------------------------------------- one row per age check attempt
create table if not exists public.age_checks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  provider text not null,
  provider_session text not null,
  result text not null default 'pending' check (result in ('pending', 'passed', 'failed')),
  method text,                       -- how they passed: 'face_estimate', 'id_document' or 'digital_id'
  created_at timestamptz not null default now(),
  decided_at timestamptz,
  unique (provider, provider_session)
);
create index if not exists age_checks_user on public.age_checks (user_id, created_at desc);
alter table public.age_checks enable row level security;
revoke all on public.age_checks from public, anon, authenticated;

alter table public.profiles add column if not exists age_verified_at timestamptz;

create or replace function public.age_check_required() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select age_check_required from public.app_settings), false);
$$;

create or replace function public.age_check_passed(u uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = u and age_verified_at is not null)
      or exists (select 1 from public.age_checks where user_id = u and result = 'passed');
$$;

-- What the app needs to know before and after sign-up.
create or replace function public.age_check_state() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'required', public.age_check_required(),
    'provider', (select age_check_provider from public.app_settings),
    'passed', public.age_check_passed(auth.uid()),
    'pending', exists (select 1 from public.age_checks where user_id = auth.uid() and result = 'pending'),
    'failed_today', (select count(*) from public.age_checks where user_id = auth.uid() and result = 'failed' and created_at > now() - interval '1 day')
  );
$$;

-- ---------------------------------------------------------------- sign-up now needs a passed check (when switched on)
-- Same as 0003, plus the age check. It now runs with the owner's rights so that the profiles table
-- can be closed to direct inserts: before this, a profile could be created without any age check.
create or replace function public.api_sign_up(p_name text, p_birth_date date) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := (now() at time zone 'Australia/Perth')::date;
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if p_birth_date is null or p_birth_date > today or p_birth_date < date '1900-01-01' then
    raise exception 'Enter your date of birth.';
  end if;
  if p_birth_date > (today - interval '18 years')::date then
    raise exception 'Seshhon is for people aged 18 and over.';
  end if;
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 24 then
    raise exception 'Enter a first name of up to 24 characters.';
  end if;
  if public.age_check_required() and not public.age_check_passed(auth.uid()) then
    raise exception 'Finish the age check first.';
  end if;
  insert into public.profiles (id, name, adult_confirmed_at, age_verified_at)
  values (auth.uid(), btrim(p_name), now(),
          (select max(decided_at) from public.age_checks where user_id = auth.uid() and result = 'passed'))
  on conflict (id) do update set name = excluded.name;
  return '{}'::jsonb;
end;
$$;
revoke all on function public.api_sign_up(text, date) from public, anon, authenticated;
grant execute on function public.api_sign_up(text, date) to authenticated;

-- Profiles are only created through api_sign_up now.
revoke insert on public.profiles from authenticated;
drop policy if exists profiles_insert on public.profiles;

-- People who signed up before the check was switched on stay hidden (Red) until they pass it.
create or replace function public.set_status(new_colour public.status_colour) returns public.statuses
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  result public.statuses;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if new_colour <> 'off' and public.age_check_required() and not public.age_check_passed(me) then
    raise exception 'Finish the age check first.';
  end if;
  insert into public.statuses (user_id, colour, expires_at, updated_at)
  values (
    me, new_colour,
    case new_colour when 'on' then now() + interval '4 hours' when 'thinking' then now() + interval '2 hours' else null end,
    now()
  )
  on conflict (user_id) do update
    set colour = excluded.colour, expires_at = excluded.expires_at, updated_at = excluded.updated_at
  returning * into result;
  return result;
end;
$$;

-- ---------------------------------------------------------------- called only by the Edge Function (service role)
-- Before a new check: refuses if already passed or after 5 attempts in a day (each check costs money).
create or replace function public.age_check_can_start(p_user uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if public.age_check_passed(p_user) then raise exception 'You have already passed the age check.'; end if;
  if (select count(*) from public.age_checks where user_id = p_user and created_at > now() - interval '1 day') >= 5 then
    raise exception 'Too many age check attempts today. Try again tomorrow.';
  end if;
  return jsonb_build_object('provider', (select age_check_provider from public.app_settings));
end;
$$;

create or replace function public.age_check_begin(p_user uuid, p_provider text, p_session text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare new_id uuid;
begin
  -- Any older unfinished attempt is abandoned: only the newest one counts.
  update public.age_checks set result = 'failed', decided_at = now() where user_id = p_user and result = 'pending';
  insert into public.age_checks (user_id, provider, provider_session) values (p_user, p_provider, p_session)
  returning id into new_id;
  return jsonb_build_object('id', new_id);
end;
$$;

create or replace function public.age_check_latest(p_user uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce((
    select jsonb_build_object('id', c.id, 'provider', c.provider, 'provider_session', c.provider_session, 'result', c.result)
    from public.age_checks c where c.user_id = p_user order by c.created_at desc limit 1
  ), 'null'::jsonb);
$$;

create or replace function public.age_check_decide(p_check uuid, p_result text, p_method text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare who uuid;
begin
  if p_result not in ('passed', 'failed') then raise exception 'Unknown result %', p_result; end if;
  update public.age_checks set result = p_result, method = p_method, decided_at = now()
  where id = p_check and result = 'pending' returning user_id into who;
  if who is not null and p_result = 'passed' then
    update public.profiles set age_verified_at = now() where id = who and age_verified_at is null;
  end if;
  return jsonb_build_object('result', p_result);
end;
$$;

-- Deleting an account also removes its age check records.
create or replace function public.forget_age_checks() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  delete from public.age_checks where user_id = old.id;
  return old;
end;
$$;
drop trigger if exists profiles_forget_age_checks on public.profiles;
create trigger profiles_forget_age_checks after delete on public.profiles
  for each row execute function public.forget_age_checks();

revoke all on function public.age_check_required(), public.age_check_passed(uuid), public.age_check_state(),
  public.age_check_can_start(uuid), public.age_check_begin(uuid, text, text), public.age_check_latest(uuid),
  public.age_check_decide(uuid, text, text), public.forget_age_checks()
  from public, anon, authenticated;
grant execute on function public.age_check_state() to authenticated;
grant execute on function public.set_status(public.status_colour) to authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.age_check_can_start(uuid), public.age_check_begin(uuid, text, text),
      public.age_check_latest(uuid), public.age_check_decide(uuid, text, text) to service_role;
  end if;
end;
$$;

-- ======================= 0006_security_hardening.sql
-- Security hardening after a review of the whole database (October 2026).
--   1. Anything added to the database later starts locked, instead of open to everyone.
--   2. A blocked person can no longer undo the block or turn it into a friendship.
--   3. Only the functions can change a sesh, so its start time can't be moved to keep it alive.
--   4. Limits on friend requests, reports and rating tags, so one account can't flood the database.
--   5. Old data is deleted: a sesh (who joined, the votes, the chat) as soon as it ends, used deal codes after the night,
--      and sign-ins that never finished signing up after 2 days.
-- Safe to run more than once.

-- ---------------------------------------------------------------- 1. new tables and functions start locked
-- Supabase gives signed-out and signed-in visitors full rights on anything new in the public
-- schema. Each migration so far has taken those rights back by hand; this stops them being
-- handed out in the first place, so a forgotten "revoke" can't leave a new table open.
-- From now on a new table or function needs an explicit "grant" before the app can use it.
alter default privileges in schema public revoke all on tables from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;
-- Postgres lets everyone (PUBLIC) call new functions, and that default can only be removed for all schemas at once.
alter default privileges revoke execute on functions from public;

-- ---------------------------------------------------------------- 2. blocks stay blocked
-- Before: the person asked in any friendship row could change its state, including a block row
-- (block_user makes the blocker the requester, so the blocked person is the addressee). They could
-- set a block to 'accepted' and see the blocker's status again, or delete it and send a new request.
-- Now the person asked can only accept a pending request, and only the blocker can remove a block.
-- Blocking always goes through block_user().
drop policy if exists friendships_answer on public.friendships;
create policy friendships_answer on public.friendships for update to authenticated
  using (addressee = auth.uid() and state = 'requested')
  with check (addressee = auth.uid() and state = 'accepted');

drop policy if exists friendships_remove on public.friendships;
create policy friendships_remove on public.friendships for delete to authenticated
  using (
    (state <> 'blocked' and (requester = auth.uid() or addressee = auth.uid()))
    or (state = 'blocked' and requester = auth.uid())
  );

-- At most 30 friend requests a day per person, however they are sent.
create or replace function public.limit_friend_requests() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.state = 'requested' and (
    select count(*) from public.friendships
    where requester = new.requester and state <> 'blocked' and created_at > now() - interval '1 day'
  ) >= 30 then
    raise exception 'You have sent a lot of friend requests today. Try again tomorrow.';
  end if;
  return new;
end;
$$;
drop trigger if exists friendships_rate_limit on public.friendships;
create trigger friendships_rate_limit before insert on public.friendships
  for each row execute function public.limit_friend_requests();

-- ---------------------------------------------------------------- 3. seshes change only through functions
-- end_sesh(), lock_sesh() and start_sesh() all run with the owner's rights, so the app never
-- needs to write to the table directly. Before, the creator could edit any column, for example
-- moving created_at forward so a sesh (and its chat) never expired.
revoke insert, update, delete on public.seshes from authenticated;
drop policy if exists seshes_end on public.seshes;

-- ---------------------------------------------------------------- 4. limits on what one account can store
-- rate_venue() limits tags, but a direct write to the table could store any number of any size.
-- "not valid" means rows already there are not re-checked; every new or changed row is.
alter table public.ratings drop constraint if exists ratings_tags_limit;
alter table public.ratings add constraint ratings_tags_limit
  check (cardinality(tags) <= 5 and char_length(array_to_string(tags, '')) <= 120) not valid;

-- Same as 0004, plus at most 20 reports a day per person.
create or replace function public.report_message(p_message uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  m public.messages;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if (select count(*) from public.reports where reporter = me and created_at > now() - interval '1 day') >= 20 then
    raise exception 'You have sent a lot of reports today. Try again tomorrow.';
  end if;
  select * into m from public.messages where id = p_message;
  if not found or not public.is_sesh_member(m.sesh_id, me) then raise exception 'That message is no longer there.'; end if;
  insert into public.reports (reporter, reported, sesh_id, message_body, reason)
  values (me, m.sender, m.sesh_id, m.body, left(coalesce(p_reason, ''), 200));
  return '{}'::jsonb;
end;
$$;

-- ---------------------------------------------------------------- 5. delete old data
-- Australian Privacy Principle 11.2: personal information that is no longer needed is destroyed.

-- Ending a sesh deletes it straight away, with who joined, the votes and the chat.
-- (Before, it was only marked as ended and kept.)
create or replace function public.end_sesh(p_sesh uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  delete from public.seshes where id = p_sesh and creator = auth.uid();
  if not found then raise exception 'Only the person who started the sesh can end it.'; end if;
  return '{}'::jsonb;
end;
$$;
revoke all on function public.end_sesh(uuid) from public, anon;
grant execute on function public.end_sesh(uuid) to authenticated;
create or replace function public.purge_old_data() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer := 0; k integer;
begin
  -- Seshes that have ended, or run out (8 hours after they started), with who joined, the votes and any chat left.
  delete from public.seshes where ended_at is not null or created_at < now() - interval '8 hours';
  get diagnostics k = row_count; n := n + k;
  -- Deal codes: a record is only needed for the night, so the same deal can't be used twice.
  delete from public.redemptions where night < public.night_of() - 1;
  get diagnostics k = row_count; n := n + k;
  -- Sign-ins that never finished signing up (no profile) after 2 days, e.g. under-18s or spam.
  -- Their age check records go with them. Only on real Supabase, where auth.users has these columns.
  begin
    execute $q$
      delete from auth.users u
      where u.is_anonymous and u.created_at < now() - interval '2 days'
        and not exists (select 1 from public.profiles p where p.id = u.id)
    $q$;
    get diagnostics k = row_count; n := n + k;
  exception when undefined_column or insufficient_privilege then
    null;
  end;
  return n;
end;
$$;

-- Chat clean-up (which also runs now and then when people chat) clears old data too.
create or replace function public.purge_chat() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  delete from public.messages m
  where m.created_at < now() - interval '8 hours'
     or exists (select 1 from public.seshes s where s.id = m.sesh_id and (s.ended_at is not null or s.created_at < now() - interval '8 hours'));
  get diagnostics n = row_count;
  delete from public.reports where created_at < now() - interval '90 days';
  perform public.purge_old_data();
  return n;
end;
$$;

revoke all on function public.limit_friend_requests(), public.purge_old_data(), public.purge_chat()
  from public, anon, authenticated;
revoke all on function public.report_message(uuid, text) from public, anon;
grant execute on function public.report_message(uuid, text) to authenticated;

-- ---------------------------------------------------------------- schedule
-- Switch on pg_cron if this project allows it (Supabase does), then run the clean-ups every
-- 5 minutes. Earlier migrations only scheduled them if pg_cron was already on.
do $$
begin
  begin
    create extension if not exists pg_cron with schema pg_catalog;
  exception when others then
    null; -- not available here (for example the local test database); the clean-ups still run from the chat
  end;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('seshhon-expire-statuses', '*/5 * * * *', 'select public.expire_statuses()');
    perform cron.schedule('seshhon-purge-chat', '*/5 * * * *', 'select public.purge_chat()');
  end if;
end;
$$;

-- ======================= 0007_linter_fixes.sql
-- Fixes from Supabase's Security Advisor (October 2026). Safe to run more than once.

-- 1. "Function Search Path Mutable": pin these functions to the public schema, so nobody can
--    make them pick up a look-alike table or function from somewhere else.
alter function public.local_now(timestamptz) set search_path = public;
alter function public.night_of(timestamptz) set search_path = public;
alter function public.deal_is_running(public.deals, timestamptz) set search_path = public;
alter function public.new_invite_code() set search_path = public;
alter function public.check_alcohol_deal_count() set search_path = public;

-- 2. "Security Definer View" on venue_ratings. The view has to read everyone's ratings to work out
--    the averages, while people may only read their own ratings. That is now done by a function that
--    returns only the totals, and the view itself runs with the reader's own rights.
create or replace function public.venue_rating_totals()
returns table (venue_id uuid, average numeric, ratings bigint)
language sql stable security definer set search_path = public as $$
  select r.venue_id, round(avg(r.stars)::numeric, 1), count(*)
  from public.ratings r group by r.venue_id;
$$;
revoke all on function public.venue_rating_totals() from public, anon, authenticated;
grant execute on function public.venue_rating_totals() to authenticated;

create or replace view public.venue_ratings as
  select t.venue_id, t.average, t.ratings from public.venue_rating_totals() t;
alter view public.venue_ratings set (security_invoker = true);
revoke all on public.venue_ratings from public, anon, authenticated;
grant select on public.venue_ratings to authenticated;

-- ======================= 0008_username_login.sql
-- Optional username and password, so people can get back into their account on a new phone.
-- No email address is asked for or stored. Behind the scenes Supabase Auth needs an "email" to log in
-- with, so the app uses <username>@users.seshon.invalid, a domain that can never receive mail.
-- Instead of "forgot password" emails, each person gets a one-time recovery code to save.
--
-- Needs in Supabase: Authentication > Sign In / Providers > Email switched ON (for password logins),
-- with "Confirm email" left ON so nobody can make accounts with real email addresses.
-- Safe to run more than once.

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

-- ---------------------------------------------------------------- tables (nobody reads these directly)
create table if not exists public.account_logins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  username text not null unique check (username ~ '^[a-z0-9_]{3,20}$'),
  recovery_hash text not null,          -- bcrypt hash of the recovery code; the code itself is never stored
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.account_logins enable row level security;
revoke all on public.account_logins from public, anon, authenticated;

-- Wrong recovery codes, so each username gets at most 5 tries a day. Kept for a day.
create table if not exists public.recovery_attempts (
  username text not null,
  at timestamptz not null default now()
);
create index if not exists recovery_attempts_username on public.recovery_attempts (username, at);
alter table public.recovery_attempts enable row level security;
revoke all on public.recovery_attempts from public, anon, authenticated;

-- ---------------------------------------------------------------- helpers
create or replace function public.login_email(p_username text) returns text
language sql immutable set search_path = public as $$
  select p_username || '@users.seshon.invalid';
$$;

-- 16 characters with no look-alikes (no I, L, O, 0 or 1), shown as XXXX-XXXX-XXXX-XXXX.
create or replace function public.new_recovery_code() returns text
language plpgsql volatile set search_path = public as $$
declare
  alphabet text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  bytes bytea := extensions.gen_random_bytes(16);
  code text := '';
begin
  for i in 0..15 loop
    code := code || substr(alphabet, 1 + get_byte(bytes, i) % 31, 1);
    if i in (3, 7, 11) then code := code || '-'; end if;
  end loop;
  return code;
end;
$$;

-- Recovery codes are compared without dashes, spaces or case.
create or replace function public.recovery_code_key(p_code text) returns text
language sql immutable set search_path = public as $$
  select upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
$$;

create or replace function public.check_new_password(p_password text) returns void
language plpgsql immutable set search_path = public as $$
begin
  if char_length(coalesce(p_password, '')) < 10 then raise exception 'Use a password of at least 10 characters.'; end if;
  if octet_length(p_password) > 72 then raise exception 'Use a password of at most 72 characters.'; end if;
end;
$$;

-- ---------------------------------------------------------------- what the app calls

-- Add (or change) your username and password. Returns a new recovery code to save.
create or replace function public.save_account(p_username text, p_password text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  uname text := lower(btrim(coalesce(p_username, '')));
  mail text;
  code text := public.new_recovery_code();
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.profiles where id = me) then raise exception 'Finish signing up first.'; end if;
  if uname !~ '^[a-z0-9_]{3,20}$' then raise exception 'Pick a username of 3 to 20 letters, numbers or _.'; end if;
  perform public.check_new_password(p_password);
  mail := public.login_email(uname);
  if exists (select 1 from public.account_logins where username = uname and user_id <> me)
     or exists (select 1 from auth.users where lower(email) = mail and id <> me) then
    raise exception 'That username is taken.';
  end if;

  update auth.users
  set email = mail,
      encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf', 10)),
      email_confirmed_at = coalesce(email_confirmed_at, now()),
      is_anonymous = false,
      raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb) || '{"provider": "email", "providers": ["email"]}'::jsonb,
      updated_at = now()
  where id = me;

  -- Supabase keeps one "identity" per sign-in method.
  delete from auth.identities where user_id = me and provider = 'email';
  insert into auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (me::text, me, jsonb_build_object('sub', me::text, 'email', mail, 'email_verified', true), 'email', now(), now(), now());

  insert into public.account_logins (user_id, username, recovery_hash)
  values (me, uname, extensions.crypt(public.recovery_code_key(code), extensions.gen_salt('bf', 8)))
  on conflict (user_id) do update
    set username = excluded.username, recovery_hash = excluded.recovery_hash, updated_at = now();
  return jsonb_build_object('username', uname, 'recovery_code', code);
end;
$$;

-- Your username, or null if you haven't saved your account.
create or replace function public.my_account() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('username', username) from public.account_logins where user_id = auth.uid();
$$;

-- Set a new password with the recovery code. Called from a new phone (signed in anonymously first,
-- so the bot check applies). The used code stops working and a new one is returned.
-- Wrong codes return a message instead of an error, so the attempt is counted.
create or replace function public.recover_account(p_username text, p_code text, p_password text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uname text := lower(btrim(coalesce(p_username, '')));
  l public.account_logins;
  code text := public.new_recovery_code();
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  perform public.check_new_password(p_password);
  delete from public.recovery_attempts where at < now() - interval '1 day';
  if (select count(*) from public.recovery_attempts where username = uname) >= 5 then
    return jsonb_build_object('ok', false, 'message', 'Too many tries for that username. Try again tomorrow.');
  end if;
  select * into l from public.account_logins where username = uname;
  if not found or l.recovery_hash <> extensions.crypt(public.recovery_code_key(p_code), l.recovery_hash) then
    insert into public.recovery_attempts (username) values (uname);
    return jsonb_build_object('ok', false, 'message', 'That username and recovery code don''t match.');
  end if;

  update auth.users set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf', 10)), updated_at = now()
  where id = l.user_id;
  -- Sign the account out everywhere else, in case someone else had it.
  begin
    delete from auth.sessions where user_id = l.user_id;
  exception when undefined_table then null;
  end;
  update public.account_logins
  set recovery_hash = extensions.crypt(public.recovery_code_key(code), extensions.gen_salt('bf', 8)), updated_at = now()
  where user_id = l.user_id;
  delete from public.recovery_attempts where username = uname;
  return jsonb_build_object('ok', true, 'username', uname, 'recovery_code', code);
end;
$$;

-- ---------------------------------------------------------------- clean-up
-- Same as 0006, except unfinished sign-ins now also include anyone who tried to sign up straight to
-- Supabase Auth with an email address (switched on for password logins) and never confirmed it.
create or replace function public.purge_old_data() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer := 0; k integer;
begin
  delete from public.seshes where ended_at is not null or created_at < now() - interval '8 hours';
  get diagnostics k = row_count; n := n + k;
  delete from public.redemptions where night < public.night_of() - 1;
  get diagnostics k = row_count; n := n + k;
  begin
    execute $q$
      delete from auth.users u
      where (u.is_anonymous or u.email_confirmed_at is null) and u.created_at < now() - interval '2 days'
        and not exists (select 1 from public.profiles p where p.id = u.id)
    $q$;
    get diagnostics k = row_count; n := n + k;
  exception when undefined_column or insufficient_privilege then
    null;
  end;
  return n;
end;
$$;
revoke all on function public.purge_old_data() from public, anon, authenticated;

-- ---------------------------------------------------------------- permissions
revoke all on function public.login_email(text), public.new_recovery_code(), public.recovery_code_key(text),
  public.check_new_password(text), public.save_account(text, text), public.my_account(),
  public.recover_account(text, text, text)
  from public, anon, authenticated;
grant execute on function public.save_account(text, text), public.my_account(), public.recover_account(text, text, text)
  to authenticated;

-- ======================= 0009_venue_map.sql
-- Venue map: the app shows venues on a map and filters them by distance.
-- Only venue positions come from the database. A person's own location stays on their phone:
-- the app measures distances there and never sends or stores where anyone is.

create or replace function public.venue_pins()
returns jsonb
language sql stable security invoker set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'lat', v.lat, 'lng', v.lng)), '[]'::jsonb)
  from public.venues v
  where v.lat between -90 and 90 and v.lng between -180 and 180;
$$;
revoke all on function public.venue_pins() from public, anon, authenticated;
grant execute on function public.venue_pins() to authenticated;

-- Pins for the three example venues (made-up places around Northbridge, Perth).
update public.venues set lat = -31.9478, lng = 115.8571 where id = 'a0000000-0000-4000-8000-000000000001' and lat is null;
update public.venues set lat = -31.9465, lng = 115.8605 where id = 'a0000000-0000-4000-8000-000000000002' and lat is null;
update public.venues set lat = -31.9512, lng = 115.8540 where id = 'a0000000-0000-4000-8000-000000000003' and lat is null;

-- ======================= 0010_osm_venues.sql
-- Real venues imported from OpenStreetMap. osm_id (for example "node/123") ties a venue to its
-- OpenStreetMap entry, so running a newer import updates venues instead of adding them twice.
alter table public.venues add column if not exists osm_id text;
create unique index if not exists venues_osm_id_key on public.venues (osm_id);

-- ======================= 0011_women_safety.sql
-- Women-only mode and easier blocking.
--
-- Anyone can tell SeshOn their gender. It is optional, private, and never shown to anyone:
-- not to friends, not in a sesh, not in the app state of anyone else. It lives in its own
-- table in a "private" schema that the app's API cannot read at all.
--
-- A woman can switch on women-only mode. While it is on, people who have not told SeshOn they
-- are a woman cannot:
--   - see her green or amber status (to them she just looks red),
--   - send her a friend request from her invite link,
--   - see, join or chat in a sesh she started.
-- Turning it on also drops pending friend requests to her from those people, and takes them
-- out of a sesh she is running. Seshes started by someone else are that person's sesh: if she
-- joins one, the people in it can see her name there.
--
-- Also adds block_request(), so a friend request can be blocked without accepting it first.

create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;

create table if not exists private.safety (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  gender text check (gender in ('woman', 'man', 'nonbinary')),
  women_only boolean not null default false,
  updated_at timestamptz not null default now(),
  check (not women_only or gender = 'woman')
);
alter table private.safety enable row level security;
revoke all on private.safety from public, anon, authenticated;

-- ---------------------------------------------------------------- helpers
-- True when the person asking should not see "owner" because owner is in women-only mode and
-- the person asking has not said they are a woman. It lives in the private schema, so the app
-- cannot call it directly to test other people; only the access rules below use it.
create or replace function private.hidden_from_me(owner uuid) returns boolean
language sql stable security definer set search_path = public, private as $$
  select coalesce(
    owner <> auth.uid()
    and exists (select 1 from private.safety s where s.user_id = owner and s.women_only)
    and not exists (select 1 from private.safety s where s.user_id = auth.uid() and s.gender = 'woman'),
    false);
$$;
revoke all on function private.hidden_from_me(uuid) from public, anon;
grant execute on function private.hidden_from_me(uuid) to authenticated;

-- ---------------------------------------------------------------- access rules
-- Same rules as 0002, plus "not hidden from me".

drop policy if exists statuses_read on public.statuses;
create policy statuses_read on public.statuses for select to authenticated using (
  user_id = auth.uid()
  or (colour <> 'off' and expires_at > now() and public.are_friends(user_id, auth.uid()) and public.i_am_visible()
      and not private.hidden_from_me(user_id))
);

drop policy if exists seshes_read on public.seshes;
create policy seshes_read on public.seshes for select to authenticated using (
  creator = auth.uid() or public.is_sesh_member(id, auth.uid())
  or (public.are_friends(creator, auth.uid()) and public.i_am_visible() and not private.hidden_from_me(creator))
);

drop policy if exists members_read on public.sesh_members;
create policy members_read on public.sesh_members for select to authenticated using (
  user_id = auth.uid() or public.is_sesh_member(sesh_id, auth.uid())
  or (public.are_friends(public.sesh_creator(sesh_id), auth.uid()) and public.i_am_visible()
      and not private.hidden_from_me(public.sesh_creator(sesh_id)))
);

drop policy if exists members_join on public.sesh_members;
create policy members_join on public.sesh_members for insert to authenticated with check (
  user_id = auth.uid()
  and (public.sesh_creator(sesh_id) = auth.uid()
       or (public.are_friends(public.sesh_creator(sesh_id), auth.uid()) and not private.hidden_from_me(public.sesh_creator(sesh_id))))
);

-- ---------------------------------------------------------------- invite links
-- Same as 0002, but a new request to someone in women-only mode from someone who has not said
-- they are a woman gets the same answer as a bad link, so it does not give her gender away.
create or replace function public.request_friend(p_code text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  other public.profiles;
  f public.friendships;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.profiles where id = me) then raise exception 'Finish signing up first.'; end if;
  select * into other from public.profiles where invite_code = upper(btrim(coalesce(p_code, '')));
  if not found then raise exception 'That invite link is not valid.'; end if;
  if other.id = me then raise exception 'That is your own invite link.'; end if;

  select * into f from public.friendships
  where (requester = me and addressee = other.id) or (requester = other.id and addressee = me);
  if found then
    if f.state = 'blocked' then raise exception 'That invite link is not valid.'; end if;
    if f.state = 'requested' and f.addressee = me then
      update public.friendships set state = 'accepted' where id = f.id;
      return jsonb_build_object('name', other.name, 'state', 'accepted');
    end if;
    return jsonb_build_object('name', other.name, 'state', f.state);
  end if;

  if private.hidden_from_me(other.id) then raise exception 'That invite link is not valid.'; end if;
  insert into public.friendships (requester, addressee) values (me, other.id);
  return jsonb_build_object('name', other.name, 'state', 'requested');
end;
$$;

-- ---------------------------------------------------------------- your own settings

-- Your gender (or null) and whether women-only mode is on. Only ever about the person asking.
create or replace function public.my_safety() returns jsonb
language sql stable security definer set search_path = public, private as $$
  select coalesce(
    (select jsonb_build_object('gender', s.gender, 'women_only', s.women_only) from private.safety s where s.user_id = auth.uid()),
    jsonb_build_object('gender', null, 'women_only', false));
$$;

-- p_gender: 'woman', 'man', 'nonbinary', or null / '' to not say.
create or replace function public.set_safety(p_gender text, p_women_only boolean) returns jsonb
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  g text := nullif(btrim(coalesce(p_gender, '')), '');
  wo boolean := coalesce(p_women_only, false);
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.profiles where id = me) then raise exception 'Finish signing up first.'; end if;
  if g is not null and g not in ('woman', 'man', 'nonbinary') then raise exception 'Pick one of the options, or leave it blank.'; end if;
  if wo and g is distinct from 'woman' then raise exception 'Women-only mode is for women.'; end if;

  -- Keep nothing when there is nothing to keep.
  if g is null and not wo then
    delete from private.safety where user_id = me;
    return public.my_safety();
  end if;

  insert into private.safety (user_id, gender, women_only, updated_at) values (me, g, wo, now())
  on conflict (user_id) do update set gender = excluded.gender, women_only = excluded.women_only, updated_at = now();

  if wo then
    -- Pending requests to her from people who have not said they are a woman.
    delete from public.friendships f
    where f.addressee = me and f.state = 'requested'
      and not exists (select 1 from private.safety s where s.user_id = f.requester and s.gender = 'woman');
    -- The same people leave any sesh she is running.
    delete from public.venue_votes v
    using public.seshes x
    where v.sesh_id = x.id and x.creator = me and x.ended_at is null and v.user_id <> me
      and not exists (select 1 from private.safety s where s.user_id = v.user_id and s.gender = 'woman');
    delete from public.sesh_members m
    using public.seshes x
    where m.sesh_id = x.id and x.creator = me and x.ended_at is null and m.user_id <> me
      and not exists (select 1 from private.safety s where s.user_id = m.user_id and s.gender = 'woman');
  end if;
  return public.my_safety();
end;
$$;

-- ---------------------------------------------------------------- block a request
-- Block the other person in a friend request (to you or from you) or a friendship.
create or replace function public.block_request(p_friendship uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  other uuid;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  select case when requester = me then addressee else requester end into other
  from public.friendships
  where id = p_friendship and (requester = me or addressee = me) and state <> 'blocked';
  if other is null then raise exception 'That request is no longer there.'; end if;
  return public.block_user(other);
end;
$$;

revoke all on function public.my_safety(), public.set_safety(text, boolean), public.block_request(uuid) from public, anon;
grant execute on function public.my_safety(), public.set_safety(text, boolean), public.block_request(uuid) to authenticated;

-- ======================= 0012_women_nonbinary_mode.sql
-- Opens women-only mode (0011) to non-binary people.
-- The mode can now be turned on by a woman or a non-binary person. While it is on, only people
-- who have told SeshOn they are a woman or non-binary can see their status, add them, or see,
-- join and chat in seshes they start. Gender stays private, as in 0011.

do $$
declare c text;
begin
  for c in
    select conname from pg_constraint
    where conrelid = 'private.safety'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%women_only%'
  loop
    execute format('alter table private.safety drop constraint %I', c);
  end loop;
end;
$$;
alter table private.safety add constraint safety_mode_needs_gender check (not women_only or gender in ('woman', 'nonbinary'));

-- True when "u" has said they are a woman or non-binary. Private, like hidden_from_me.
create or replace function private.in_safe_group(u uuid) returns boolean
language sql stable security definer set search_path = public, private as $$
  select exists (select 1 from private.safety s where s.user_id = u and s.gender in ('woman', 'nonbinary'));
$$;
revoke all on function private.in_safe_group(uuid) from public, anon, authenticated;

create or replace function private.hidden_from_me(owner uuid) returns boolean
language sql stable security definer set search_path = public, private as $$
  select coalesce(
    owner <> auth.uid()
    and exists (select 1 from private.safety s where s.user_id = owner and s.women_only)
    and not private.in_safe_group(auth.uid()),
    false);
$$;

create or replace function public.set_safety(p_gender text, p_women_only boolean) returns jsonb
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  g text := nullif(btrim(coalesce(p_gender, '')), '');
  wo boolean := coalesce(p_women_only, false);
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.profiles where id = me) then raise exception 'Finish signing up first.'; end if;
  if g is not null and g not in ('woman', 'man', 'nonbinary') then raise exception 'Pick one of the options, or leave it blank.'; end if;
  if wo and (g is null or g not in ('woman', 'nonbinary')) then raise exception 'This mode is for women and non-binary people.'; end if;

  -- Keep nothing when there is nothing to keep.
  if g is null and not wo then
    delete from private.safety where user_id = me;
    return public.my_safety();
  end if;

  insert into private.safety (user_id, gender, women_only, updated_at) values (me, g, wo, now())
  on conflict (user_id) do update set gender = excluded.gender, women_only = excluded.women_only, updated_at = now();

  if wo then
    -- Pending requests to them from people outside the group.
    delete from public.friendships f
    where f.addressee = me and f.state = 'requested' and not private.in_safe_group(f.requester);
    -- The same people leave any sesh they are running.
    delete from public.venue_votes v
    using public.seshes x
    where v.sesh_id = x.id and x.creator = me and x.ended_at is null and v.user_id <> me and not private.in_safe_group(v.user_id);
    delete from public.sesh_members m
    using public.seshes x
    where m.sesh_id = x.id and x.creator = me and x.ended_at is null and m.user_id <> me and not private.in_safe_group(m.user_id);
  end if;
  return public.my_safety();
end;
$$;

-- ======================= 0013_profile_photos.sql
-- Profile photos: a small picture on each person's circle.
--
-- The app shrinks the photo on the phone to a 160 x 160 JPEG (about 10 KB) and saves it here as
-- text in a column called "picture" (a column named photo would trip the check that age checks
-- never store photos), so no file storage or new web address is needed. Nobody can read this table directly.
-- friend_photos() hands out only:
--   - your own photo,
--   - photos of accepted friends you have not blocked and who have not blocked you,
--   - and, once women-only mode (migrations 0011 and 0012) is installed, not the photo of someone
--     in that mode to a person that mode keeps out. It asks private.hidden_from_me(), the same
--     check that hides their status, so the two can never disagree.
-- A photo is removed with the account (on delete cascade) or when its owner removes it.

create table if not exists public.profile_photos (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  picture text not null check (picture ~ '^data:image/jpeg;base64,[A-Za-z0-9+/]+=*$' and char_length(picture) <= 60000),
  updated_at timestamptz not null default now()
);
alter table public.profile_photos enable row level security;
revoke all on public.profile_photos from public, anon, authenticated;

-- Women-only mode lives in migrations 0011 and 0012, which may be installed before or after this one.
-- This asks it when it is there, and otherwise hides nothing.
create or replace function public.photo_hidden_from_me(owner uuid) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare hidden boolean;
begin
  if to_regprocedure('private.hidden_from_me(uuid)') is null then return false; end if;
  execute 'select private.hidden_from_me($1)' into hidden using owner;
  return coalesce(hidden, false);
end $$;
revoke all on function public.photo_hidden_from_me(uuid) from public, anon, authenticated;

create or replace function public.friend_photos() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'Sign in first.'; end if;
  return coalesce((
    select jsonb_object_agg(p.user_id, p.picture)
    from public.profile_photos p
    where p.user_id = me
       or (public.are_friends(p.user_id, me) and not public.blocked_between(p.user_id, me) and not public.photo_hidden_from_me(p.user_id))
  ), '{}'::jsonb);
end $$;
revoke all on function public.friend_photos() from public, anon, authenticated;
grant execute on function public.friend_photos() to authenticated;

-- Saves your photo, or removes it when p_photo is null.
create or replace function public.set_photo(p_photo text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid();
begin
  if me is null or not exists (select 1 from public.profiles where id = me) then raise exception 'Sign in first.'; end if;
  if p_photo is null then
    delete from public.profile_photos where user_id = me;
    return jsonb_build_object('ok', true);
  end if;
  if p_photo !~ '^data:image/jpeg;base64,[A-Za-z0-9+/]+=*$' or char_length(p_photo) > 60000 then
    raise exception 'That photo could not be used. Try a different one.';
  end if;
  insert into public.profile_photos (user_id, picture) values (me, p_photo)
  on conflict (user_id) do update set picture = excluded.picture, updated_at = now();
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.set_photo(text) from public, anon, authenticated;
grant execute on function public.set_photo(text) to authenticated;

-- ======================= 0014_venues_load_once.sql
-- Venues load once instead of on every refresh. With 1,500+ real venues, sending them inside
-- api_state() (which every phone calls every few seconds) cost about 300 KB a time. api_state() now
-- leaves venues out, and the app fetches them from api_venues() when it starts, when the Map or
-- Venues tab opens, and after you rate a venue. Ratings are totalled once, not once per venue.

create or replace function public.api_venues() returns jsonb
language sql stable security invoker set search_path = public as $$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', v.id, 'name', v.name, 'kind', v.kind, 'closes', v.closes, 'is_example', v.is_example,
      'average', t.average,
      'ratings', coalesce(t.ratings, 0),
      'my_stars', coalesce(mine.stars, 0),
      'my_tags', coalesce(to_jsonb(mine.tags), '[]'::jsonb)
    )
    order by v.name
  ), '[]'::jsonb)
  from public.venues v
  left join public.venue_ratings t on t.venue_id = v.id
  left join public.ratings mine on mine.venue_id = v.id and mine.user_id = auth.uid();
$$;
revoke all on function public.api_venues() from public, anon, authenticated;
grant execute on function public.api_venues() to authenticated;

-- The same as before (migration 0004), minus 'venues'.
create or replace function public.api_state() returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'now', now(),
    'night', public.night_of(),
    'me', (
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'invite_code', p.invite_code,
        'colour', coalesce((select s.colour::text from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now()), 'off'),
        'expires_at', (select s.expires_at from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now())
      )
      from public.profiles p where p.id = auth.uid()
    ),
    'friends', coalesce((
      select jsonb_agg(
        jsonb_build_object('friendship', f.id, 'id', p.id, 'name', p.name, 'colour', coalesce(s.colour::text, 'off'), 'since', s.updated_at)
        order by case coalesce(s.colour::text, 'off') when 'on' then 0 when 'thinking' then 1 else 2 end, p.name
      )
      from public.friendships f
      join public.profiles p on p.id = case when f.requester = auth.uid() then f.addressee else f.requester end
      left join public.statuses s on s.user_id = p.id
      where f.state = 'accepted'
    ), '[]'::jsonb),
    'requests_in', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.requester
      where f.state = 'requested' and f.addressee = auth.uid()
    ), '[]'::jsonb),
    'requests_out', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.addressee
      where f.state = 'requested' and f.requester = auth.uid()
    ), '[]'::jsonb),
    'seshes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'mine', s.creator = auth.uid(),
          'creator_name', (select p.name from public.profiles p where p.id = s.creator),
          'locked_venue', s.locked_venue,
          'am_member', public.is_sesh_member(s.id, auth.uid()),
          'members', coalesce((
            select jsonb_agg(jsonb_build_object('id', m.user_id, 'name', p.name) order by m.joined_at)
            from public.sesh_members m left join public.profiles p on p.id = m.user_id
            where m.sesh_id = s.id
          ), '[]'::jsonb),
          'votes', coalesce((
            select jsonb_agg(jsonb_build_object('user_id', v.user_id, 'venue_id', v.venue_id, 'voted_at', v.voted_at))
            from public.venue_votes v where v.sesh_id = s.id
          ), '[]'::jsonb)
        )
        order by s.created_at desc
      )
      from public.seshes s
      where s.ended_at is null and s.created_at > now() - interval '8 hours'
    ), '[]'::jsonb),
    'deals', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', d.id, 'venue_id', d.venue_id, 'type', d.type, 'title', d.title, 'is_alcohol', d.is_alcohol,
          'start_time', to_char(d.start_time, 'HH24:MI'), 'end_time', to_char(d.end_time, 'HH24:MI'),
          'running', public.deal_is_running(d),
          'used', coalesce(r.confirmed_at is not null, false),
          'code', case when r.confirmed_at is null and r.expires_at > now() then r.code end,
          'code_expires_at', case when r.confirmed_at is null and r.expires_at > now() then r.expires_at end
        )
        order by d.start_time, d.title
      )
      from public.deals d
      left join public.redemptions r on r.deal_id = d.id and r.user_id = auth.uid() and r.night = public.night_of()
      where d.active
    ), '[]'::jsonb),
    'staff_venues', coalesce((
      select jsonb_agg(vs.venue_id) from public.venue_staff vs where vs.user_id = auth.uid()
    ), '[]'::jsonb),
    'blocked', public.blocked_list()
  );
$$;

-- ======================= 0015_venue_hours.sql
-- Opening hours. opening_hours uses OpenStreetMap's format, for example "Mo-Th 11:00-23:00; Fr,Sa 11:00-02:00".
-- The venue import fills it in from OpenStreetMap, and venue staff can change it. Once staff have set
-- the hours (hours_source = 'staff'), a later import leaves them alone.
alter table public.venues add column if not exists opening_hours text;
alter table public.venues add column if not exists hours_source text;
alter table public.venues drop constraint if exists venues_opening_hours_check;
alter table public.venues add constraint venues_opening_hours_check
  check (opening_hours is null or (char_length(opening_hours) between 1 and 255 and opening_hours !~ '[<>]'));
alter table public.venues drop constraint if exists venues_hours_source_check;
alter table public.venues add constraint venues_hours_source_check check (hours_source is null or hours_source in ('osm', 'staff'));

create or replace function public.api_venues() returns jsonb
language sql stable security invoker set search_path = public as $$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', v.id, 'name', v.name, 'kind', v.kind, 'closes', v.closes, 'is_example', v.is_example,
      'hours', v.opening_hours,
      'average', t.average,
      'ratings', coalesce(t.ratings, 0),
      'my_stars', coalesce(mine.stars, 0),
      'my_tags', coalesce(to_jsonb(mine.tags), '[]'::jsonb)
    )
    order by v.name
  ), '[]'::jsonb)
  from public.venues v
  left join public.venue_ratings t on t.venue_id = v.id
  left join public.ratings mine on mine.venue_id = v.id and mine.user_id = auth.uid();
$$;

-- Venue staff set their venue's hours. An empty value clears them ("hours unknown").
create or replace function public.set_venue_hours(p_venue uuid, p_hours text) returns void
language plpgsql security definer set search_path = public as $$
declare h text := nullif(btrim(regexp_replace(coalesce(p_hours, ''), '\s+', ' ', 'g')), '');
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.venue_staff s where s.venue_id = p_venue and s.user_id = auth.uid()) then
    raise exception 'Only staff at this venue can change its hours.';
  end if;
  if h is not null and (char_length(h) > 255 or h !~ '^[A-Za-z0-9 :;,+./-]+$') then
    raise exception 'Those hours could not be read. Use a format like: Mo-Fr 16:00-24:00; Sa,Su 12:00-02:00';
  end if;
  update public.venues set opening_hours = h, hours_source = 'staff' where id = p_venue;
end;
$$;
revoke all on function public.set_venue_hours(uuid, text) from public, anon, authenticated;
grant execute on function public.set_venue_hours(uuid, text) to authenticated;

-- Example venue hours, so the app has something to show before a real import.
update public.venues set opening_hours = 'Mo-Su 16:00-01:00', hours_source = 'osm' where id = 'a0000000-0000-4000-8000-000000000001' and opening_hours is null;
update public.venues set opening_hours = 'Tu-Su 12:00-24:00; Mo off', hours_source = 'osm' where id = 'a0000000-0000-4000-8000-000000000002' and opening_hours is null;
update public.venues set opening_hours = 'We-Sa 19:00-24:00', hours_source = 'osm' where id = 'a0000000-0000-4000-8000-000000000003' and opening_hours is null;

-- ======================= 0016_google_ratings.sql
-- Google ratings, shown next to SeshOn's own ratings once a Google Places key is set up.
-- Google's terms allow keeping a venue's Google place ID (venues.places_id) but not its rating, so
-- the google-rating Edge Function fetches the rating fresh each time and nothing else is stored.
-- Each look-up costs money, so each person gets at most 100 a day.

create table if not exists public.google_lookups (
  user_id uuid not null references public.profiles (id) on delete cascade,
  day date not null,
  n integer not null default 0,
  primary key (user_id, day)
);
alter table public.google_lookups enable row level security;   -- no policies: only the functions below touch it
revoke all on public.google_lookups from public, anon, authenticated;

-- Called by the Edge Function (service role only): counts the look-up and returns what Google needs.
create or replace function public.google_lookup_start(p_user uuid, p_venue uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare used integer; v public.venues;
begin
  select * into v from public.venues where id = p_venue;
  if v.id is null then raise exception 'That venue is no longer listed.'; end if;
  insert into public.google_lookups (user_id, day, n) values (p_user, (now() at time zone 'Australia/Perth')::date, 1)
  on conflict (user_id, day) do update set n = google_lookups.n + 1
  returning n into used;
  if used > 100 then raise exception 'Google ratings are paused for you until tomorrow.'; end if;
  return jsonb_build_object('name', v.name, 'lat', v.lat, 'lng', v.lng, 'place', v.places_id);
end;
$$;

-- Called by the Edge Function (service role only) to remember a venue's Google place ID.
create or replace function public.google_set_place(p_venue uuid, p_place text) returns void
language sql security definer set search_path = public as $$
  update public.venues set places_id = left(p_place, 300) where id = p_venue;
$$;

-- Old look-up counts are not needed.
create or replace function public.purge_google_lookups() returns void
language sql security definer set search_path = public as $$
  delete from public.google_lookups where day < (now() at time zone 'Australia/Perth')::date - 1;
$$;

revoke all on function public.google_lookup_start(uuid, uuid), public.google_set_place(uuid, text), public.purge_google_lookups()
  from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.google_lookup_start(uuid, uuid), public.google_set_place(uuid, text) to service_role;
  end if;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('seshon-purge-google-lookups', '17 4 * * *', 'select public.purge_google_lookups()');
  end if;
end;
$$;

-- ======================= 0018_email_two_step.sql
-- Email two-step login. When someone saves a username and password, they also give an email address
-- and confirm it with a 6-digit code. After that, every new login asks for a fresh code sent to that
-- email, as well as the password.
--
-- The email address is private: it lives in the "private" schema, which the app's API cannot read,
-- and nobody (not even the owner) gets it back in full, only a hint like s•••@gmail.com.
-- The codes are sent by the email-code Edge Function (supabase/functions/email-code), which holds the
-- email service key. Only a bcrypt hash of each code is stored.
--
-- How a login is held back until the code is typed: the Supabase "Customize Access Token" hook
-- (Authentication > Hooks) runs two_step_token_hook() every time a sign-in token is made. If the account
-- has email codes on and this sign-in hasn't had its code yet, the token gets the role "needs_code",
-- which can only check a code and nothing else. After the code, the app fetches a fresh token and gets
-- the normal "authenticated" role. If the hook ever fails, it lets the login through as before.
--
-- Accounts saved before this change keep logging in with just their password until they add an email.
-- A recovery code still gets you back in if you lose your email.
-- Safe to run more than once. Run it BEFORE switching on the hook.

create schema if not exists private;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

-- ---------------------------------------------------------------- the waiting role
do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'needs_code') then
    create role needs_code nologin noinherit;
  end if;
  -- The API (PostgREST) signs in as "authenticator" and switches to the role in each token.
  if exists (select 1 from pg_roles where rolname = 'authenticator') then
    execute 'grant needs_code to authenticator';
  end if;
end $$;
grant usage on schema public to needs_code;

-- ---------------------------------------------------------------- tables (nobody reads these directly)
create table if not exists private.two_step (
  user_id uuid primary key references auth.users (id) on delete cascade,
  email text,                       -- the confirmed address; null until the first code is typed
  pending_email text,               -- an address waiting for its code
  code_hash text,                   -- bcrypt hash of the latest code
  code_purpose text check (code_purpose in ('setup', 'login')),
  code_expires timestamptz,
  code_tries integer not null default 0,
  ticket_hash text,                 -- after a recovery code: lets the next login skip the email code once
  ticket_expires timestamptz,
  updated_at timestamptz not null default now()
);
alter table private.two_step enable row level security;
revoke all on private.two_step from public, anon, authenticated;

-- Sign-ins that have had their code. Rows go when the sign-in itself is gone.
create table if not exists private.two_step_sessions (
  session_id uuid primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  verified_at timestamptz not null default now()
);
create index if not exists two_step_sessions_user on private.two_step_sessions (user_id);
alter table private.two_step_sessions enable row level security;
revoke all on private.two_step_sessions from public, anon, authenticated;

-- Codes sent, so each account gets at most 5 emails an hour and 20 a day. Kept for a day.
create table if not exists private.two_step_sends (
  user_id uuid not null references auth.users (id) on delete cascade,
  at timestamptz not null default now()
);
create index if not exists two_step_sends_user on private.two_step_sends (user_id, at);
alter table private.two_step_sends enable row level security;
revoke all on private.two_step_sends from public, anon, authenticated;

-- ---------------------------------------------------------------- helpers
-- The sign-in (Supabase Auth session) the current request belongs to.
create or replace function private.my_session() returns uuid
language plpgsql stable set search_path = public as $$
begin
  return (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'session_id')::uuid;
exception when others then
  return null;
end;
$$;

-- s•••@gmail.com
create or replace function private.email_hint(p_email text) returns text
language sql immutable set search_path = public as $$
  select case when p_email is null then null
    else left(split_part(p_email, '@', 1), 1) || '•••@' || split_part(p_email, '@', 2) end;
$$;

create or replace function private.session_verified(p_user uuid, p_session uuid) returns boolean
language sql stable security definer set search_path = public, private as $$
  select p_session is not null
     and exists (select 1 from private.two_step_sessions s where s.session_id = p_session and s.user_id = p_user);
$$;

create or replace function private.mark_verified(p_user uuid, p_session uuid) returns void
language plpgsql security definer set search_path = public, private as $$
begin
  if p_session is null then return; end if;
  insert into private.two_step_sessions (session_id, user_id) values (p_session, p_user)
  on conflict (session_id) do nothing;
  -- Tidy up sign-ins that no longer exist.
  begin
    delete from private.two_step_sessions s
    where s.user_id = p_user and not exists (select 1 from auth.sessions a where a.id = s.session_id);
  exception when undefined_table then null;
  end;
end;
$$;

-- ---------------------------------------------------------------- the token hook
-- Supabase Auth calls this every time it makes a sign-in token (logging in and every refresh).
create or replace function public.two_step_token_hook(event jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, private as $$
declare
  claims jsonb := event -> 'claims';
  uid uuid;
  sid uuid;
begin
  begin
    uid := (event ->> 'user_id')::uuid;
    sid := (claims ->> 'session_id')::uuid;
    if claims ->> 'role' = 'authenticated'
       and exists (select 1 from private.two_step t where t.user_id = uid and t.email is not null)
       and not private.session_verified(uid, sid) then
      claims := jsonb_set(claims, '{role}', '"needs_code"');
    end if;
  exception when others then
    return event;   -- never block a login because of this check
  end;
  return jsonb_build_object('claims', claims);
end;
$$;

-- ---------------------------------------------------------------- what the app calls

-- Whether this sign-in still needs its email code.
create or replace function public.two_step_state() returns jsonb
language plpgsql stable security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  t private.two_step;
begin
  if me is null then return jsonb_build_object('on', false, 'needed', false); end if;
  select * into t from private.two_step where user_id = me;
  return jsonb_build_object(
    'on', t.email is not null,
    'needed', t.email is not null and not private.session_verified(me, private.my_session()),
    'hint', private.email_hint(coalesce(t.email, t.pending_email))
  );
end;
$$;

-- Your username, and the hint for your login email.
create or replace function public.my_account() returns jsonb
language sql stable security definer set search_path = public, private as $$
  select jsonb_build_object('username', l.username, 'email', private.email_hint(t.email), 'pending_email', private.email_hint(t.pending_email))
  from public.account_logins l left join private.two_step t on t.user_id = l.user_id
  where l.user_id = auth.uid();
$$;

-- Makes a code to email. Only the email-code Edge Function calls this (with the service key), after
-- checking who is asking with Supabase Auth. Returns the address and the code to send.
--   'setup': start using (or change to) p_email. Needs a saved username, and if codes are already on,
--            a sign-in that has had its code.
--   'login': a code for the sign-in p_session.
create or replace function public.two_step_make_code(p_user uuid, p_session uuid, p_purpose text, p_email text default null)
returns jsonb
language plpgsql security definer set search_path = public, private as $$
declare
  t private.two_step;
  mail text := lower(btrim(coalesce(p_email, '')));
  code text := lpad((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint % 1000000)::text, 6, '0');
begin
  if p_user is null then raise exception 'Sign in first.'; end if;
  select * into t from private.two_step where user_id = p_user;
  if p_purpose = 'setup' then
    if not exists (select 1 from public.account_logins where user_id = p_user) then raise exception 'Save a username and password first.'; end if;
    if mail !~ '^[^@\s]+@[^@\s]+\.[a-z]{2,}$' or char_length(mail) > 254 then raise exception 'Enter a real email address.'; end if;
    if t.email is not null and not private.session_verified(p_user, p_session) then raise exception 'Type the code from your email first.'; end if;
  elsif p_purpose = 'login' then
    if t.email is null then raise exception 'This account doesn''t use email codes.'; end if;
    if private.session_verified(p_user, p_session) then raise exception 'You''re already logged in.'; end if;
    mail := t.email;
  else
    raise exception 'Unknown code type.';
  end if;

  delete from private.two_step_sends where at < now() - interval '1 day';
  if (select count(*) from private.two_step_sends where user_id = p_user and at > now() - interval '1 hour') >= 5
     or (select count(*) from private.two_step_sends where user_id = p_user) >= 20 then
    raise exception 'Too many codes sent. Wait a while, then try again.';
  end if;
  insert into private.two_step_sends (user_id) values (p_user);

  insert into private.two_step (user_id, pending_email, code_hash, code_purpose, code_expires, code_tries, updated_at)
  values (p_user, case when p_purpose = 'setup' then mail end, extensions.crypt(code, extensions.gen_salt('bf', 8)), p_purpose, now() + interval '10 minutes', 0, now())
  on conflict (user_id) do update set
    pending_email = case when p_purpose = 'setup' then mail else private.two_step.pending_email end,
    code_hash = excluded.code_hash, code_purpose = excluded.code_purpose, code_expires = excluded.code_expires,
    code_tries = 0, updated_at = now();
  return jsonb_build_object('email', mail, 'code', code);
end;
$$;

-- Check the code from the email. Right code: this sign-in is let in (and for 'setup', the email is saved).
-- Wrong codes return a message, and after 5 the code stops working.
create or replace function public.two_step_check(p_code text) returns jsonb
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  t private.two_step;
  typed text := regexp_replace(coalesce(p_code, ''), '\D', '', 'g');
begin
  if me is null then raise exception 'Sign in first.'; end if;
  select * into t from private.two_step where user_id = me for update;
  if not found or t.code_hash is null or t.code_expires < now() or t.code_tries >= 5 then
    return jsonb_build_object('ok', false, 'message', 'That code has run out. Send a new one.');
  end if;
  if t.code_hash <> extensions.crypt(typed, t.code_hash) then
    update private.two_step set code_tries = code_tries + 1 where user_id = me;
    return jsonb_build_object('ok', false, 'message', 'That code isn''t right. Check the email and try again.');
  end if;
  if t.code_purpose = 'setup' then
    update private.two_step set email = pending_email, pending_email = null, code_hash = null, code_tries = 0, updated_at = now() where user_id = me;
  else
    update private.two_step set code_hash = null, code_tries = 0, updated_at = now() where user_id = me;
  end if;
  perform private.mark_verified(me, private.my_session());
  return jsonb_build_object('ok', true, 'email', private.email_hint(coalesce(t.pending_email, t.email)));
end;
$$;

-- After a recovery code, the first login skips the email code once (for when the email is lost too).
create or replace function public.two_step_use_ticket(p_ticket text) returns boolean
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  t private.two_step;
begin
  if me is null or coalesce(p_ticket, '') = '' then return false; end if;
  select * into t from private.two_step where user_id = me for update;
  if not found or t.ticket_hash is null or t.ticket_expires < now()
     or t.ticket_hash <> extensions.crypt(p_ticket, t.ticket_hash) then
    return false;
  end if;
  update private.two_step set ticket_hash = null, ticket_expires = null where user_id = me;
  perform private.mark_verified(me, private.my_session());
  return true;
end;
$$;

-- Same as 0008, plus a one-time ticket so the login straight after a recovery doesn't need the email.
create or replace function public.recover_account(p_username text, p_code text, p_password text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uname text := lower(btrim(coalesce(p_username, '')));
  l public.account_logins;
  code text := public.new_recovery_code();
  ticket text := encode(extensions.gen_random_bytes(18), 'hex');
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  perform public.check_new_password(p_password);
  delete from public.recovery_attempts where at < now() - interval '1 day';
  if (select count(*) from public.recovery_attempts where username = uname) >= 5 then
    return jsonb_build_object('ok', false, 'message', 'Too many tries for that username. Try again tomorrow.');
  end if;
  select * into l from public.account_logins where username = uname;
  if not found or l.recovery_hash <> extensions.crypt(public.recovery_code_key(p_code), l.recovery_hash) then
    insert into public.recovery_attempts (username) values (uname);
    return jsonb_build_object('ok', false, 'message', 'That username and recovery code don''t match.');
  end if;

  update auth.users set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf', 10)), updated_at = now()
  where id = l.user_id;
  -- Sign the account out everywhere else, in case someone else had it.
  begin
    delete from auth.sessions where user_id = l.user_id;
  exception when undefined_table then null;
  end;
  delete from private.two_step_sessions where user_id = l.user_id;
  update private.two_step set ticket_hash = extensions.crypt(ticket, extensions.gen_salt('bf', 8)), ticket_expires = now() + interval '15 minutes'
  where user_id = l.user_id;
  update public.account_logins
  set recovery_hash = extensions.crypt(public.recovery_code_key(code), extensions.gen_salt('bf', 8)), updated_at = now()
  where user_id = l.user_id;
  delete from public.recovery_attempts where username = uname;
  return jsonb_build_object('ok', true, 'username', uname, 'recovery_code', code, 'ticket', ticket);
end;
$$;

-- ---------------------------------------------------------------- permissions
revoke all on function private.my_session(), private.email_hint(text), private.session_verified(uuid, uuid),
  private.mark_verified(uuid, uuid), public.two_step_token_hook(jsonb), public.two_step_state(), public.my_account(),
  public.two_step_make_code(uuid, uuid, text, text), public.two_step_check(text), public.two_step_use_ticket(text),
  public.recover_account(text, text, text)
  from public, anon, authenticated;
grant execute on function public.two_step_state(), public.two_step_check(text), public.two_step_use_ticket(text)
  to authenticated, needs_code;
grant execute on function public.my_account(), public.recover_account(text, text, text) to authenticated;
grant execute on function public.two_step_make_code(uuid, uuid, text, text) to service_role;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'supabase_auth_admin') then
    execute 'grant usage on schema public to supabase_auth_admin';
    execute 'grant execute on function public.two_step_token_hook(jsonb) to supabase_auth_admin';
  end if;
end $$;

-- ======================= 0020_venue_buzz.sql
-- Busy and trending venues for the map's glows and tags.
-- Counts only, never who: no names, no ids of people, no locations. A venue shows as busy only when at
-- least 2 people in live seshes are heading there (voted for it, or in a sesh that locked it in), so a
-- glow can't point at one person. Trending means at least 2 people rated it in the last 7 days.
-- Seshes and votes are deleted when a sesh ends, so "busy" only ever reflects tonight.

create or replace function public.api_buzz() returns jsonb
language sql stable security definer set search_path = public as $$
  with live as (
    select s.id, s.locked_venue from public.seshes s
    where s.ended_at is null and s.created_at > now() - interval '8 hours'
  ),
  heading as (
    select l.locked_venue as venue_id, m.user_id from live l join public.sesh_members m on m.sesh_id = l.id
    where l.locked_venue is not null
    union
    select v.venue_id, v.user_id from live l join public.venue_votes v on v.sesh_id = l.id
    where l.locked_venue is null
  ),
  busy as (
    select venue_id, count(distinct user_id) as people from heading group by venue_id having count(distinct user_id) >= 2
  ),
  trend as (
    select venue_id, count(*) as recent from public.ratings
    where updated_at > now() - interval '7 days' group by venue_id having count(*) >= 2
    order by count(*) desc limit 10
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', coalesce(b.venue_id, t.venue_id),
    'busy', case when b.people >= 10 then 3 when b.people >= 5 then 2 when b.people >= 2 then 1 else 0 end,
    'trending', t.venue_id is not null
  )), '[]'::jsonb)
  from busy b full join trend t on t.venue_id = b.venue_id
  where auth.uid() is not null;
$$;
revoke all on function public.api_buzz() from public, anon, authenticated;
grant execute on function public.api_buzz() to authenticated;

-- ======================= 0021_add_friends_by_username.sql
-- Add a friend by typing their username, and pick a username and password when you sign up.
-- Same rules as an invite link: a request the other person accepts, nothing found for anyone who
-- has blocked you or is hidden from you (women and non-binary only mode), and no list of usernames
-- to browse. Only an exact username works, and each person gets 20 misses a day.
-- Needs 0008 (usernames) and 0011 (private schema). Safe to run more than once.

-- Misses, so nobody can guess usernames one after another. Kept for a day.
create table if not exists private.username_misses (
  user_id uuid not null references auth.users (id) on delete cascade,
  at timestamptz not null default now()
);
create index if not exists username_misses_user on private.username_misses (user_id, at);
alter table private.username_misses enable row level security;
revoke all on private.username_misses from public, anon, authenticated;

-- Whether a username is free, so sign up can say "taken" before making the account.
-- Says nothing else about whoever has it.
create or replace function public.username_free(p_username text) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare uname text := lower(btrim(coalesce(p_username, '')));
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if uname !~ '^[a-z0-9_]{3,20}$' then raise exception 'Pick a username of 3 to 20 letters, numbers or _.'; end if;
  return not exists (select 1 from public.account_logins where username = uname and user_id <> auth.uid())
     and not exists (select 1 from auth.users where lower(email) = public.login_email(uname) and id <> auth.uid());
end;
$$;

-- Send a friend request to an exact username. A wrong username, someone who blocked you, and someone
-- you can't see all get the same answer, so it never gives away who is on the app or why.
-- Misses return a message instead of an error, so the miss is counted.
create or replace function public.request_friend_by_username(p_username text) returns jsonb
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  uname text := lower(btrim(coalesce(p_username, '')));
  other public.profiles;
  f public.friendships;
  nobody constant jsonb := jsonb_build_object('ok', false, 'message', 'No one with that username. Check the spelling with your friend.');
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.profiles where id = me) then raise exception 'Finish signing up first.'; end if;
  uname := ltrim(uname, '@');
  if uname !~ '^[a-z0-9_]{3,20}$' then
    return jsonb_build_object('ok', false, 'message', 'Usernames are 3 to 20 letters, numbers or _.');
  end if;

  delete from private.username_misses where at < now() - interval '1 day';
  if (select count(*) from private.username_misses where user_id = me) >= 20 then
    return jsonb_build_object('ok', false, 'message', 'Too many tries today. Send your friend your invite link instead.');
  end if;

  select p.* into other from public.account_logins l join public.profiles p on p.id = l.user_id where l.username = uname;
  if not found then
    insert into private.username_misses (user_id) values (me);
    return nobody;
  end if;
  if other.id = me then return jsonb_build_object('ok', false, 'message', 'That''s your own username.'); end if;

  select * into f from public.friendships
  where (requester = me and addressee = other.id) or (requester = other.id and addressee = me);
  if found then
    if f.state = 'blocked' then
      insert into private.username_misses (user_id) values (me);
      return nobody;
    end if;
    if f.state = 'requested' and f.addressee = me then
      update public.friendships set state = 'accepted' where id = f.id;
      return jsonb_build_object('ok', true, 'name', other.name, 'state', 'accepted');
    end if;
    return jsonb_build_object('ok', true, 'name', other.name, 'state', f.state::text);
  end if;

  if private.hidden_from_me(other.id) then
    insert into private.username_misses (user_id) values (me);
    return nobody;
  end if;
  insert into public.friendships (requester, addressee) values (me, other.id);
  return jsonb_build_object('ok', true, 'name', other.name, 'state', 'requested');
end;
$$;

revoke all on function public.username_free(text), public.request_friend_by_username(text) from public, anon, authenticated;
grant execute on function public.username_free(text), public.request_friend_by_username(text) to authenticated;

-- ======================= 0022_email_recovery_code.sql
-- Email the recovery code as well as showing it. When a recovery code is made (at sign up, on a password
-- change, or after using the old one) and the account has a confirmed email, the app asks the email-code
-- Edge Function to send it there. The code itself is still never stored: the app passes it to the
-- function, and this check only lets it through if it matches the account's current recovery code.
-- Needs 0018. Safe to run more than once.

-- Only the email-code Edge Function calls this (with the service key). p_user is whoever is signed in
-- (after a recovery, that is a temporary sign-in on the new phone). Returns the address to send to.
create or replace function public.two_step_recovery_target(p_user uuid, p_username text, p_code text) returns jsonb
language plpgsql security definer set search_path = public, private as $$
declare
  l public.account_logins;
  mail text;
begin
  if p_user is null then raise exception 'Sign in first.'; end if;
  select * into l from public.account_logins where username = lower(btrim(coalesce(p_username, '')));
  if not found or l.recovery_hash <> extensions.crypt(public.recovery_code_key(p_code), l.recovery_hash) then
    raise exception 'That recovery code is not the current one.';
  end if;
  select email into mail from private.two_step where user_id = l.user_id;
  if mail is null then raise exception 'Confirm your email first.'; end if;

  delete from private.two_step_sends where at < now() - interval '1 day';
  if (select count(*) from private.two_step_sends where user_id = l.user_id and at > now() - interval '1 hour') >= 5
     or (select count(*) from private.two_step_sends where user_id = l.user_id) >= 20 then
    raise exception 'Too many emails sent. Wait a while, then try again.';
  end if;
  insert into private.two_step_sends (user_id) values (l.user_id);
  return jsonb_build_object('email', mail);
end;
$$;

revoke all on function public.two_step_recovery_target(uuid, text, text) from public, anon, authenticated;
grant execute on function public.two_step_recovery_target(uuid, text, text) to service_role;

-- ======================= 0023_remember_this_phone.sql
-- Remember this phone. Once the email code has been typed on a phone, the app can ask for a secret that lets
-- that phone's next logins skip the code for 30 days. The password is still needed every time.
-- The secret lives only on the phone; the database keeps a SHA-256 hash of it (it is 32 random bytes, so a
-- fast hash is enough). Changing the password, or using a recovery code, forgets every remembered phone.
-- Needs 0018. Safe to run more than once.

create table if not exists private.two_step_devices (
  token_hash text primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null
);
create index if not exists two_step_devices_user on private.two_step_devices (user_id, created_at);
alter table private.two_step_devices enable row level security;
revoke all on private.two_step_devices from public, anon, authenticated;

create or replace function private.device_hash(p_token text) returns text
language sql immutable set search_path = public as $$
  select encode(extensions.digest(coalesce(p_token, ''), 'sha256'), 'hex');
$$;

-- Called on a login that has just had its email code. Returns the secret for the phone to keep.
create or replace function public.two_step_remember_device() returns text
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  token text := encode(extensions.gen_random_bytes(32), 'hex');
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from private.two_step where user_id = me and email is not null) then return null; end if;
  if not private.session_verified(me, private.my_session()) then raise exception 'Type the code from your email first.'; end if;
  delete from private.two_step_devices where user_id = me and expires_at < now();
  insert into private.two_step_devices (token_hash, user_id, expires_at) values (private.device_hash(token), me, now() + interval '30 days');
  -- At most 10 remembered phones; the oldest are forgotten first.
  delete from private.two_step_devices where token_hash in (
    select token_hash from private.two_step_devices where user_id = me order by created_at desc offset 10);
  return token;
end;
$$;

-- Called on a new login that is waiting for its email code. A remembered phone's secret lets it in instead.
create or replace function public.two_step_use_device(p_token text) returns boolean
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
begin
  if me is null or coalesce(p_token, '') = '' then return false; end if;
  if not exists (select 1 from private.two_step_devices
                 where token_hash = private.device_hash(p_token) and user_id = me and expires_at > now()) then
    return false;
  end if;
  perform private.mark_verified(me, private.my_session());
  return true;
end;
$$;

-- A new password (a password change, or a recovery code) forgets every remembered phone.
create or replace function private.forget_devices_on_password() returns trigger
language plpgsql security definer set search_path = public, private as $$
begin
  if new.encrypted_password is distinct from old.encrypted_password then
    delete from private.two_step_devices where user_id = new.id;
  end if;
  return new;
end;
$$;
drop trigger if exists two_step_forget_devices on auth.users;
create trigger two_step_forget_devices after update of encrypted_password on auth.users
  for each row execute function private.forget_devices_on_password();

revoke all on function private.device_hash(text), public.two_step_remember_device(), public.two_step_use_device(text),
  private.forget_devices_on_password()
  from public, anon, authenticated;
grant execute on function public.two_step_remember_device() to authenticated;
grant execute on function public.two_step_use_device(text) to authenticated, needs_code;

-- ======================= 0024_private_seshes.sql
-- Private seshes. Starting a sesh can now be private: only the friends picked for it (and the person who
-- started it) can see it, see who is in it, or join it. Everyone else sees nothing, not even that it exists.
-- The person who started it can invite more friends later. An ordinary sesh works exactly as before.
-- Invites are deleted with the sesh. Needs 0011. Safe to run more than once.

alter table public.seshes add column if not exists private boolean not null default false;

create table if not exists public.sesh_invites (
  sesh_id uuid not null references public.seshes (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  primary key (sesh_id, user_id)
);
create index if not exists sesh_invites_user on public.sesh_invites (user_id);
alter table public.sesh_invites enable row level security;   -- no policies: only the functions below use it
revoke all on public.sesh_invites from public, anon, authenticated;

-- True when the sesh is private and the person asking was not picked for it (and did not start it).
create or replace function private.sesh_closed_to_me(p_sesh uuid) returns boolean
language sql stable security definer set search_path = public, private as $$
  select coalesce((
    select x.private and x.creator <> auth.uid()
       and not exists (select 1 from public.sesh_invites i where i.sesh_id = x.id and i.user_id = auth.uid())
    from public.seshes x where x.id = p_sesh), false);
$$;
revoke all on function private.sesh_closed_to_me(uuid) from public, anon;
grant execute on function private.sesh_closed_to_me(uuid) to authenticated;

-- Who was picked for a private sesh, only for the person who started it (null for anyone else).
create or replace function private.sesh_invited(p_sesh uuid) returns jsonb
language sql stable security definer set search_path = public, private as $$
  select case when x.private and x.creator = auth.uid() then coalesce((
    select jsonb_agg(i.user_id) from public.sesh_invites i where i.sesh_id = x.id), '[]'::jsonb) end
  from public.seshes x where x.id = p_sesh;
$$;
revoke all on function private.sesh_invited(uuid) from public, anon;
grant execute on function private.sesh_invited(uuid) to authenticated;

-- ---------------------------------------------------------------- access rules
-- Same as 0011, plus "not a private sesh I wasn't picked for" for friends who aren't in it.
drop policy if exists seshes_read on public.seshes;
create policy seshes_read on public.seshes for select to authenticated using (
  creator = auth.uid() or public.is_sesh_member(id, auth.uid())
  or (public.are_friends(creator, auth.uid()) and public.i_am_visible() and not private.hidden_from_me(creator)
      and not private.sesh_closed_to_me(id))
);

drop policy if exists members_read on public.sesh_members;
create policy members_read on public.sesh_members for select to authenticated using (
  user_id = auth.uid() or public.is_sesh_member(sesh_id, auth.uid())
  or (public.are_friends(public.sesh_creator(sesh_id), auth.uid()) and public.i_am_visible()
      and not private.hidden_from_me(public.sesh_creator(sesh_id)) and not private.sesh_closed_to_me(sesh_id))
);

drop policy if exists members_join on public.sesh_members;
create policy members_join on public.sesh_members for insert to authenticated with check (
  user_id = auth.uid()
  and (public.sesh_creator(sesh_id) = auth.uid()
       or (public.are_friends(public.sesh_creator(sesh_id), auth.uid()) and not private.hidden_from_me(public.sesh_creator(sesh_id))
           and not private.sesh_closed_to_me(sesh_id)))
);

-- ---------------------------------------------------------------- starting and inviting
-- Adds the picked friends to a private sesh. Only accepted friends count; anyone else is skipped.
create or replace function private.invite_friends(p_sesh uuid, p_friends uuid[]) returns integer
language plpgsql security definer set search_path = public, private as $$
declare n integer;
begin
  insert into public.sesh_invites (sesh_id, user_id)
  select p_sesh, f from (select distinct unnest(coalesce(p_friends, '{}'::uuid[])) as f) x
  where f <> auth.uid() and public.are_friends(f, auth.uid())
  on conflict do nothing;
  get diagnostics n = row_count;
  return n;
end;
$$;

create or replace function public.start_private_sesh(p_friends uuid[]) returns public.seshes
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  s public.seshes;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.statuses where user_id = me and colour = 'on' and expires_at > now()) then
    raise exception 'You need to be On to start a sesh.';
  end if;
  if exists (select 1 from public.seshes where creator = me and ended_at is null and created_at > now() - interval '8 hours') then
    raise exception 'You already have a sesh going. End it first to start a private one.';
  end if;
  if coalesce(array_length(p_friends, 1), 0) = 0 then raise exception 'Pick at least one friend.'; end if;
  if coalesce(array_length(p_friends, 1), 0) > 50 then raise exception 'Pick up to 50 friends.'; end if;
  insert into public.seshes (creator, private) values (me, true) returning * into s;
  insert into public.sesh_members (sesh_id, user_id) values (s.id, me);
  if private.invite_friends(s.id, p_friends) = 0 then raise exception 'Pick at least one friend.'; end if;
  return s;
end;
$$;

-- The person who started a private sesh can invite more friends while it is on.
create or replace function public.invite_to_sesh(p_sesh uuid, p_friends uuid[]) returns jsonb
language plpgsql security definer set search_path = public, private as $$
declare n integer;
begin
  if not exists (select 1 from public.seshes where id = p_sesh and creator = auth.uid() and private
                 and ended_at is null and created_at > now() - interval '8 hours') then
    raise exception 'Only the person who started a private sesh can invite people to it.';
  end if;
  if coalesce(array_length(p_friends, 1), 0) > 50 then raise exception 'Pick up to 50 friends.'; end if;
  n := private.invite_friends(p_sesh, p_friends);
  return jsonb_build_object('ok', true, 'invited', n);
end;
$$;

revoke all on function private.invite_friends(uuid, uuid[]), public.start_private_sesh(uuid[]), public.invite_to_sesh(uuid, uuid[])
  from public, anon, authenticated;
grant execute on function public.start_private_sesh(uuid[]), public.invite_to_sesh(uuid, uuid[]) to authenticated;

-- ---------------------------------------------------------------- app state
-- Same as 0014, plus whether each sesh is private and, for the person who started it, who was picked.
create or replace function public.api_state() returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'now', now(),
    'night', public.night_of(),
    'me', (
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'invite_code', p.invite_code,
        'colour', coalesce((select s.colour::text from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now()), 'off'),
        'expires_at', (select s.expires_at from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now())
      )
      from public.profiles p where p.id = auth.uid()
    ),
    'friends', coalesce((
      select jsonb_agg(
        jsonb_build_object('friendship', f.id, 'id', p.id, 'name', p.name, 'colour', coalesce(s.colour::text, 'off'), 'since', s.updated_at)
        order by case coalesce(s.colour::text, 'off') when 'on' then 0 when 'thinking' then 1 else 2 end, p.name
      )
      from public.friendships f
      join public.profiles p on p.id = case when f.requester = auth.uid() then f.addressee else f.requester end
      left join public.statuses s on s.user_id = p.id
      where f.state = 'accepted'
    ), '[]'::jsonb),
    'requests_in', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.requester
      where f.state = 'requested' and f.addressee = auth.uid()
    ), '[]'::jsonb),
    'requests_out', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.addressee
      where f.state = 'requested' and f.requester = auth.uid()
    ), '[]'::jsonb),
    'seshes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'mine', s.creator = auth.uid(),
          'creator_name', (select p.name from public.profiles p where p.id = s.creator),
          'locked_venue', s.locked_venue,
          'private', s.private,
          'invited', private.sesh_invited(s.id),
          'am_member', public.is_sesh_member(s.id, auth.uid()),
          'members', coalesce((
            select jsonb_agg(jsonb_build_object('id', m.user_id, 'name', p.name) order by m.joined_at)
            from public.sesh_members m left join public.profiles p on p.id = m.user_id
            where m.sesh_id = s.id
          ), '[]'::jsonb),
          'votes', coalesce((
            select jsonb_agg(jsonb_build_object('user_id', v.user_id, 'venue_id', v.venue_id, 'voted_at', v.voted_at))
            from public.venue_votes v where v.sesh_id = s.id
          ), '[]'::jsonb)
        )
        order by s.created_at desc
      )
      from public.seshes s
      where s.ended_at is null and s.created_at > now() - interval '8 hours'
    ), '[]'::jsonb),
    'deals', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', d.id, 'venue_id', d.venue_id, 'type', d.type, 'title', d.title, 'is_alcohol', d.is_alcohol,
          'start_time', to_char(d.start_time, 'HH24:MI'), 'end_time', to_char(d.end_time, 'HH24:MI'),
          'running', public.deal_is_running(d),
          'used', coalesce(r.confirmed_at is not null, false),
          'code', case when r.confirmed_at is null and r.expires_at > now() then r.code end,
          'code_expires_at', case when r.confirmed_at is null and r.expires_at > now() then r.expires_at end
        )
        order by d.start_time, d.title
      )
      from public.deals d
      left join public.redemptions r on r.deal_id = d.id and r.user_id = auth.uid() and r.night = public.night_of()
      where d.active
    ), '[]'::jsonb),
    'staff_venues', coalesce((
      select jsonb_agg(vs.venue_id) from public.venue_staff vs where vs.user_id = auth.uid()
    ), '[]'::jsonb),
    'blocked', public.blocked_list()
  );
$$;

-- ======================= 0025_planned_seshes.sql
-- Planned seshes. A sesh can be planned for a date and time up to 2 weeks ahead. The friends it's for (all
-- friends, or only the ones picked, as with a private sesh) can see it straight away, say they're in, vote on
-- where to go and chat about it. It goes live at the planned time, or earlier if the person who planned it
-- taps "Start now".
--
-- A sesh's created_at is when it starts: for a planned sesh that is the planned time. So every rule that
-- already counts "8 hours after it started" (the clean-up, chat, joining, voting, the Sesh Map stops) counts
-- from the planned start, and a planned sesh that never gets going is deleted 8 hours after its start time
-- with everything in it. Cancelling one deletes it straight away, like ending a sesh.
--
-- A planned sesh doesn't count as "on" until it starts: it never makes a venue glow busy, and it doesn't
-- stop anyone starting a sesh now.
--
-- Also adds a private pres (pre-drinks) address the host can add to a sesh: see "pres address" below.
-- Needs 0024. Safe to run more than once.

create index if not exists seshes_creator_start on public.seshes (creator, created_at);

-- ---------------------------------------------------------------- planning one
-- p_at: when it starts. p_friends: null or empty for all friends, or the friends picked for a private one.
create or replace function public.plan_sesh(p_at timestamptz, p_friends uuid[] default null) returns public.seshes
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  picked boolean := coalesce(array_length(p_friends, 1), 0) > 0;
  s public.seshes;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if p_at is null or p_at < now() + interval '5 minutes' then raise exception 'Pick a time later than now.'; end if;
  if p_at > now() + interval '14 days' then raise exception 'You can plan a sesh up to 2 weeks ahead.'; end if;
  if (select count(*) from public.seshes where creator = me and ended_at is null and created_at > now()) >= 5 then
    raise exception 'You already have 5 seshes planned. Cancel one first.';
  end if;
  if coalesce(array_length(p_friends, 1), 0) > 50 then raise exception 'Pick up to 50 friends.'; end if;
  insert into public.seshes (creator, private, created_at) values (me, picked, p_at) returning * into s;
  insert into public.sesh_members (sesh_id, user_id) values (s.id, me);
  if picked and private.invite_friends(s.id, p_friends) = 0 then raise exception 'Pick at least one friend.'; end if;
  return s;
end;
$$;

-- The person who planned it can start it early. It then runs (and is deleted) like any sesh started now.
create or replace function public.start_planned_sesh(p_sesh uuid) returns public.seshes
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  s public.seshes;
begin
  if not exists (select 1 from public.seshes where id = p_sesh and creator = me and ended_at is null and created_at > now()) then
    raise exception 'Only the person who planned the sesh can start it early.';
  end if;
  if exists (select 1 from public.seshes where creator = me and ended_at is null
             and created_at <= now() and created_at > now() - interval '8 hours') then
    raise exception 'You already have a sesh going. End it first.';
  end if;
  update public.seshes set created_at = now() where id = p_sesh returning * into s;
  return s;
end;
$$;

revoke all on function public.plan_sesh(timestamptz, uuid[]), public.start_planned_sesh(uuid) from public, anon, authenticated;
grant execute on function public.plan_sesh(timestamptz, uuid[]), public.start_planned_sesh(uuid) to authenticated;

-- ---------------------------------------------------------------- starting one now
-- Same as 0002 and 0024, except a sesh planned for later doesn't count as the one you already have going.
create or replace function public.start_sesh() returns public.seshes
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  s public.seshes;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.statuses where user_id = me and colour = 'on' and expires_at > now()) then
    raise exception 'You need to be On to start a sesh.';
  end if;
  select * into s from public.seshes
  where creator = me and ended_at is null and created_at <= now() and created_at > now() - interval '8 hours'
  order by created_at desc limit 1;
  if found then
    insert into public.sesh_members (sesh_id, user_id) values (s.id, me) on conflict do nothing;
    return s;
  end if;
  insert into public.seshes (creator) values (me) returning * into s;
  insert into public.sesh_members (sesh_id, user_id) values (s.id, me);
  return s;
end;
$$;

create or replace function public.start_private_sesh(p_friends uuid[]) returns public.seshes
language plpgsql security definer set search_path = public, private as $$
declare
  me uuid := auth.uid();
  s public.seshes;
begin
  if me is null then raise exception 'Sign in first.'; end if;
  if not exists (select 1 from public.statuses where user_id = me and colour = 'on' and expires_at > now()) then
    raise exception 'You need to be On to start a sesh.';
  end if;
  if exists (select 1 from public.seshes where creator = me and ended_at is null
             and created_at <= now() and created_at > now() - interval '8 hours') then
    raise exception 'You already have a sesh going. End it first to start a private one.';
  end if;
  if coalesce(array_length(p_friends, 1), 0) = 0 then raise exception 'Pick at least one friend.'; end if;
  if coalesce(array_length(p_friends, 1), 0) > 50 then raise exception 'Pick up to 50 friends.'; end if;
  insert into public.seshes (creator, private) values (me, true) returning * into s;
  insert into public.sesh_members (sesh_id, user_id) values (s.id, me);
  if private.invite_friends(s.id, p_friends) = 0 then raise exception 'Pick at least one friend.'; end if;
  return s;
end;
$$;
revoke all on function public.start_sesh(), public.start_private_sesh(uuid[]) from public, anon, authenticated;
grant execute on function public.start_sesh(), public.start_private_sesh(uuid[]) to authenticated;

-- ---------------------------------------------------------------- chat clean-up
-- Same as 0006, except chat in a sesh that hasn't started yet is kept until the sesh itself is deleted,
-- so plans made days ahead aren't wiped after 8 hours. Started seshes work exactly as before.
create or replace function public.purge_chat() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  delete from public.messages m
  where (m.created_at < now() - interval '8 hours'
         and not exists (select 1 from public.seshes s where s.id = m.sesh_id and s.created_at > now()))
     or exists (select 1 from public.seshes s where s.id = m.sesh_id and (s.ended_at is not null or s.created_at < now() - interval '8 hours'));
  get diagnostics n = row_count;
  delete from public.reports where created_at < now() - interval '90 days';
  perform public.purge_old_data();
  return n;
end;
$$;
revoke all on function public.purge_chat() from public, anon, authenticated;

-- ---------------------------------------------------------------- busy venues
-- Same as 0020, except seshes planned for later don't make a venue glow: busy means people heading there now.
-- (If 0020 hasn't been run yet, this adds it. Run 0020 before this one, not after.)
create or replace function public.api_buzz() returns jsonb
language sql stable security definer set search_path = public as $$
  with live as (
    select s.id, s.locked_venue from public.seshes s
    where s.ended_at is null and s.created_at <= now() and s.created_at > now() - interval '8 hours'
  ),
  heading as (
    select l.locked_venue as venue_id, m.user_id from live l join public.sesh_members m on m.sesh_id = l.id
    where l.locked_venue is not null
    union
    select v.venue_id, v.user_id from live l join public.venue_votes v on v.sesh_id = l.id
    where l.locked_venue is null
  ),
  busy as (
    select venue_id, count(distinct user_id) as people from heading group by venue_id having count(distinct user_id) >= 2
  ),
  trend as (
    select venue_id, count(*) as recent from public.ratings
    where updated_at > now() - interval '7 days' group by venue_id having count(*) >= 2
    order by count(*) desc limit 10
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', coalesce(b.venue_id, t.venue_id),
    'busy', case when b.people >= 10 then 3 when b.people >= 5 then 2 when b.people >= 2 then 1 else 0 end,
    'trending', t.venue_id is not null
  )), '[]'::jsonb)
  from busy b full join trend t on t.venue_id = b.venue_id
  where auth.uid() is not null;
$$;
revoke all on function public.api_buzz() from public, anon, authenticated;
grant execute on function public.api_buzz() to authenticated;

-- ---------------------------------------------------------------- pres address
-- The person who started a sesh can add a private address for pres (pre-drinks), usually someone's home.
-- It is kept in its own table that nobody can read directly, so friends who can see the sesh can't see it.
-- Only people who have said they're in see it, and only from 4 hours before the sesh starts (the host always
-- sees what they typed). Anyone blocked by or blocking the host never sees it. It never goes on the map or
-- into venue glows, and it is deleted with the sesh.
create table if not exists private.sesh_pres (
  sesh_id uuid primary key references public.seshes (id) on delete cascade,
  address text not null check (char_length(address) between 1 and 200),
  pres_at timestamptz,
  updated_at timestamptz not null default now()
);
alter table private.sesh_pres enable row level security;   -- no policies: only the functions below use it
revoke all on private.sesh_pres from public, anon, authenticated;

-- p_address empty or null removes it. p_at (optional) is when pres starts.
create or replace function public.set_sesh_pres(p_sesh uuid, p_address text, p_at timestamptz default null) returns jsonb
language plpgsql security definer set search_path = public, private as $$
declare
  addr text := btrim(coalesce(p_address, ''));
  starts timestamptz;
begin
  select created_at into starts from public.seshes
  where id = p_sesh and creator = auth.uid() and ended_at is null and created_at > now() - interval '8 hours';
  if not found then raise exception 'Only the person who started the sesh can set the pres address.'; end if;
  if addr = '' then
    delete from private.sesh_pres where sesh_id = p_sesh;
    return jsonb_build_object('ok', true, 'removed', true);
  end if;
  if char_length(addr) > 200 then raise exception 'Keep the address under 200 characters.'; end if;
  if p_at is not null and (p_at > starts or p_at < starts - interval '12 hours') then
    raise exception 'Pres has to be on the day, before the sesh starts.';
  end if;
  insert into private.sesh_pres (sesh_id, address, pres_at) values (p_sesh, addr, p_at)
  on conflict (sesh_id) do update set address = excluded.address, pres_at = excluded.pres_at, updated_at = now();
  return jsonb_build_object('ok', true);
end;
$$;
revoke all on function public.set_sesh_pres(uuid, text, timestamptz) from public, anon, authenticated;
grant execute on function public.set_sesh_pres(uuid, text, timestamptz) to authenticated;

-- What the person asking may know about a sesh's pres: null if there is none or they aren't in the sesh,
-- {"at", "shows_at"} without the address until 4 hours before the start, then the address too.
create or replace function private.sesh_pres_for_me(p_sesh uuid) returns jsonb
language sql stable security definer set search_path = public, private as $$
  select case
    when x.creator = auth.uid() then jsonb_build_object('address', p.address, 'at', p.pres_at, 'shows_at', x.created_at - interval '4 hours')
    when public.is_sesh_member(x.id, auth.uid()) and not public.blocked_between(x.creator, auth.uid())
         and not private.hidden_from_me(x.creator) then
      case when now() >= x.created_at - interval '4 hours'
        then jsonb_build_object('address', p.address, 'at', p.pres_at, 'shows_at', x.created_at - interval '4 hours')
        else jsonb_build_object('at', p.pres_at, 'shows_at', x.created_at - interval '4 hours') end
  end
  from public.seshes x join private.sesh_pres p on p.sesh_id = x.id
  where x.id = p_sesh;
$$;
revoke all on function private.sesh_pres_for_me(uuid) from public, anon;
grant execute on function private.sesh_pres_for_me(uuid) to authenticated;

-- ---------------------------------------------------------------- app state
-- Same as 0024, plus when each sesh starts, whether it is still only planned, and its pres (as above).
create or replace function public.api_state() returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'now', now(),
    'night', public.night_of(),
    'me', (
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'invite_code', p.invite_code,
        'colour', coalesce((select s.colour::text from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now()), 'off'),
        'expires_at', (select s.expires_at from public.statuses s where s.user_id = p.id and s.colour <> 'off' and s.expires_at > now())
      )
      from public.profiles p where p.id = auth.uid()
    ),
    'friends', coalesce((
      select jsonb_agg(
        jsonb_build_object('friendship', f.id, 'id', p.id, 'name', p.name, 'colour', coalesce(s.colour::text, 'off'), 'since', s.updated_at)
        order by case coalesce(s.colour::text, 'off') when 'on' then 0 when 'thinking' then 1 else 2 end, p.name
      )
      from public.friendships f
      join public.profiles p on p.id = case when f.requester = auth.uid() then f.addressee else f.requester end
      left join public.statuses s on s.user_id = p.id
      where f.state = 'accepted'
    ), '[]'::jsonb),
    'requests_in', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.requester
      where f.state = 'requested' and f.addressee = auth.uid()
    ), '[]'::jsonb),
    'requests_out', coalesce((
      select jsonb_agg(jsonb_build_object('friendship', f.id, 'name', p.name) order by f.created_at)
      from public.friendships f join public.profiles p on p.id = f.addressee
      where f.state = 'requested' and f.requester = auth.uid()
    ), '[]'::jsonb),
    'seshes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'mine', s.creator = auth.uid(),
          'creator_name', (select p.name from public.profiles p where p.id = s.creator),
          'locked_venue', s.locked_venue,
          'private', s.private,
          'starts_at', s.created_at,
          'planned', s.created_at > now(),
          'pres', private.sesh_pres_for_me(s.id),
          'invited', private.sesh_invited(s.id),
          'am_member', public.is_sesh_member(s.id, auth.uid()),
          'members', coalesce((
            select jsonb_agg(jsonb_build_object('id', m.user_id, 'name', p.name) order by m.joined_at)
            from public.sesh_members m left join public.profiles p on p.id = m.user_id
            where m.sesh_id = s.id
          ), '[]'::jsonb),
          'votes', coalesce((
            select jsonb_agg(jsonb_build_object('user_id', v.user_id, 'venue_id', v.venue_id, 'voted_at', v.voted_at))
            from public.venue_votes v where v.sesh_id = s.id
          ), '[]'::jsonb)
        )
        order by s.created_at desc
      )
      from public.seshes s
      where s.ended_at is null and s.created_at > now() - interval '8 hours'
    ), '[]'::jsonb),
    'deals', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', d.id, 'venue_id', d.venue_id, 'type', d.type, 'title', d.title, 'is_alcohol', d.is_alcohol,
          'start_time', to_char(d.start_time, 'HH24:MI'), 'end_time', to_char(d.end_time, 'HH24:MI'),
          'running', public.deal_is_running(d),
          'used', coalesce(r.confirmed_at is not null, false),
          'code', case when r.confirmed_at is null and r.expires_at > now() then r.code end,
          'code_expires_at', case when r.confirmed_at is null and r.expires_at > now() then r.expires_at end
        )
        order by d.start_time, d.title
      )
      from public.deals d
      left join public.redemptions r on r.deal_id = d.id and r.user_id = auth.uid() and r.night = public.night_of()
      where d.active
    ), '[]'::jsonb),
    'staff_venues', coalesce((
      select jsonb_agg(vs.venue_id) from public.venue_staff vs where vs.user_id = auth.uid()
    ), '[]'::jsonb),
    'blocked', public.blocked_list()
  );
$$;

